using System.Collections.Generic;
using TMPro;
using UnityEngine;
public class BattleManager : MonoBehaviour
{
    public static BattleManager Instance { get; private set; }
    [SerializeField] private TMP_Text hpLabel;
    [SerializeField] private AudioSource sfx;
    [SerializeField] private AudioClip hitClip;
    [SerializeField] private AudioClip critClip;
    [SerializeField] private GameObject enemyPrefab;
    [SerializeField] private Transform[] spawnPoints;
    public int PlayerHp = 100;
    public int KillCount;
    private readonly List<GameObject> enemies = new List<GameObject>();

    private void Awake()
    {
        Instance = this;
        KillCount = PlayerPrefs.GetInt("kills", 0);
    }
    private void Start() => SpawnWave(3);
    public int CalculateDamage(int attack, int defense, float critChance)
    {
        bool crit = Random.value < critChance;
        int damage = Mathf.Max(1, attack - defense);
        if (crit) damage *= 2;
        sfx.PlayOneShot(crit ? critClip : hitClip);
        return damage;
    }

    public void DamagePlayer(int attack, int defense)
    {
        PlayerHp = Mathf.Max(0, PlayerHp - CalculateDamage(attack, defense, 0.1f));
        hpLabel.text = "HP " + PlayerHp;
        if (PlayerHp == 0) Save();
    }

    public void OnEnemyKilled(GameObject enemy)
    {
        enemies.Remove(enemy);
        Destroy(enemy);
        KillCount++;
        Save();
        if (enemies.Count == 0) SpawnWave(3);
    }

    public void SpawnWave(int count)
    {
        for (int i = 0; i < count; i++)
        {
            Transform point = spawnPoints[i % spawnPoints.Length];
            enemies.Add(Instantiate(enemyPrefab, point.position, point.rotation));
        }
    }
    public void Save() { PlayerPrefs.SetInt("kills", KillCount); PlayerPrefs.Save(); }
}

