// ---- Answer key ----
// Q1 (one script, guaranteed order):
//   P Awake
//   P OnEnable
//   P Start
//   P Update
//   P LateUpdate
//
// Q2: (a) X   (b) O   (c) X   (d) O   (e) O   (f) O
//     (d) and (e) hold because Player and Hud are part of the scene asset.
//
// Q3: B Awake -> B OnEnable -> B Start -> B OnDisable -> B OnEnable
//     Nothing is logged at scene load. There is no second Awake and no second Start.
//
// Q4: "P after Destroy" is logged before "P OnDestroy".
//     "P OnDisable" is logged before "P OnDestroy".

using UnityEngine;

// The initialisation pattern that follows from these guarantees.
public class PlayerStats : MonoBehaviour
{
    [SerializeField] private int maxHp = 100;

    public int CurrentHp { get; private set; }

    // Own state: Awake.
    private void Awake() => CurrentHp = maxHp;
}

public class HudController : MonoBehaviour
{
    [SerializeField] private PlayerStats player;

    private int _shownHp;

    // Another object's state: Start. Awake has been called on every active object in the scene by now.
    // Reading player.CurrentHp in Awake (or in the first OnEnable) would depend on
    // which object Unity happens to wake first.
    private void Start() => _shownHp = player.CurrentHp;
}

