using System.Collections;
using UnityEngine;

// Health and MonsterStatus are unchanged.

public class MonsterAttack : MonoBehaviour
{
    [SerializeField] private Health target;
    [SerializeField] private int damage = 10;
    [SerializeField] private float attackInterval = 2f;

    private Coroutine _loop;

    // OnEnable (not Start) so that a pooled monster restarts its loop every time it is re-activated.
    private void OnEnable()
    {
        _loop = StartCoroutine(AttackLoop());
    }

    // Setting enabled = false does NOT stop coroutines, so stop the loop explicitly.
    // OnDisable is also called on SetActive(false) and on Destroy.
    private void OnDisable()
    {
        if (_loop == null) return;   // StopCoroutine(null) throws

        StopCoroutine(_loop);        // stop with the Coroutine that StartCoroutine returned
        _loop = null;
    }

    private IEnumerator AttackLoop()
    {
        var wait = new WaitForSeconds(attackInterval);   // game time: the loop pauses while timeScale is 0
        while (true)
        {
            yield return wait;
            if (target != null) target.TakeDamage(damage);
        }
    }
}

// Put this on a scene object that outlives projectiles (for example the combat manager object).
public class HitStopController : MonoBehaviour
{
    private Coroutine _routine;

    public void Play(float realSeconds, float scale)
    {
        // Restart instead of stacking: only the latest hit restores the time scale.
        if (_routine != null) StopCoroutine(_routine);
        _routine = StartCoroutine(Routine(realSeconds, scale));
    }

    private IEnumerator Routine(float realSeconds, float scale)
    {
        Time.timeScale = scale;
        // WaitForSeconds(0.1f) at timeScale 0.05 would take 0.1 / 0.05 = 2 real seconds.
        yield return new WaitForSecondsRealtime(realSeconds);
        Time.timeScale = 1f;
        _routine = null;
    }

    // If this object is deactivated or destroyed mid hit-stop, Unity stops the coroutine and
    // the lines after the yield never run. Restore the time scale here instead.
    private void OnDisable()
    {
        if (_routine == null) return;

        StopCoroutine(_routine);
        _routine = null;
        Time.timeScale = 1f;
    }
}

public class Fireball : MonoBehaviour
{
    [SerializeField] private int damage = 40;
    [SerializeField] private float hitStopSeconds = 0.1f;
    [SerializeField] private float hitStopScale = 0.05f;

    private HitStopController _hitStop;

    // Called by the code that spawns the fireball, right after Instantiate.
    public void Init(HitStopController hitStop) => _hitStop = hitStop;

    private void OnTriggerEnter(Collider other)
    {
        if (!other.TryGetComponent(out Health health)) return;

        health.TakeDamage(damage);

        // The coroutine now runs on the controller, not on this object that is about to be destroyed.
        if (_hitStop != null) _hitStop.Play(hitStopSeconds, hitStopScale);

        Destroy(gameObject);
    }
}

