public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static bool Near(float a, float b) { return System.Math.Abs(a - b) <= 1e-4f; }

    // 상태가 기대와 같으면 null, 다르면 사유.
    static string Check(string when, AbilityCooldown c, bool ready, float remaining)
    {
        float progress = 1f - remaining / c.Duration;
        if (c.IsReady != ready) return when + ": IsReady 기대 " + ready + ", 결과 " + c.IsReady;
        if (!Near(c.Remaining, remaining)) return when + ": Remaining 기대 " + remaining + ", 결과 " + c.Remaining;
        if (!Near(c.Progress01, progress)) return when + ": Progress01 기대 " + progress + ", 결과 " + c.Progress01;
        return null;
    }

    static bool Throws(float duration)
    {
        try { new AbilityCooldown(duration); return false; }
        catch (System.ArgumentOutOfRangeException) { return true; }
    }

    public static void Main()
    {
        Run("starts-ready", () =>
        {
            var c = new AbilityCooldown(3f);
            if (!Near(c.Duration, 3f)) return "Duration 기대 3, 결과 " + c.Duration;
            return Check("생성 직후", c, true, 0f);
        });
        Run("use-starts-cooldown", () =>
        {
            var c = new AbilityCooldown(3f);
            if (!c.TryUse()) return "준비 상태에서 TryUse 가 false 를 반환";
            string e = Check("사용 직후", c, false, 3f);
            if (e != null) return e;
            c.Tick(1f);
            if (c.TryUse()) return "쿨다운 중(남은 2초)인데 TryUse 가 true 를 반환";
            return Check("실패한 TryUse 뒤", c, false, 2f);
        });
        Run("tick-to-ready", () =>
        {
            var c = new AbilityCooldown(3f);
            c.TryUse();
            c.Tick(1.5f);
            string e = Check("1.5초 경과", c, false, 1.5f);
            if (e != null) return e;
            c.Tick(1.5f);
            e = Check("3초 경과", c, true, 0f);
            if (e != null) return e;
            if (!c.TryUse()) return "쿨다운이 끝났는데 TryUse 가 false 를 반환";
            return Check("두 번째 사용 직후", c, false, 3f);
        });
        Run("overshoot-clamps", () =>
        {
            var c = new AbilityCooldown(2f);
            c.TryUse();
            c.Tick(10f);
            string e = Check("2초 쿨다운에 Tick(10)", c, true, 0f);
            if (e != null) return e;
            c.TryUse();
            return Check("초과분이 다음 쿨다운에 이월되면 안 됨", c, false, 2f);
        });
        Run("zero-and-negative-dt", () =>
        {
            var c = new AbilityCooldown(3f);
            c.Tick(1f); c.Tick(-1f);
            string e = Check("준비 상태에서 Tick", c, true, 0f);
            if (e != null) return e;
            c.TryUse();
            c.Tick(0f);
            e = Check("Tick(0)", c, false, 3f);
            if (e != null) return e;
            c.Tick(-5f);
            return Check("Tick(-5)", c, false, 3f);
        });
        Run("invalid-duration", () =>
        {
            if (!Throws(0f)) return "duration 0 에서 ArgumentOutOfRangeException 이 나지 않음";
            if (!Throws(-1f)) return "duration -1 에서 ArgumentOutOfRangeException 이 나지 않음";
            return null;
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            float[] steps = { 0f, 0.25f, 0.25f, 0.5f, 1f, -0.25f };
            for (int round = 0; round < 40; round++)
            {
                float duration = 0.25f * rng.Next(1, 17);
                var c = new AbilityCooldown(duration);
                float remaining = 0f;
                for (int i = 0; i < 60; i++)
                {
                    string op;
                    if (rng.Next(3) == 0)
                    {
                        bool expected = remaining <= 0f;
                        bool got = c.TryUse();
                        if (expected) remaining = duration;
                        op = "TryUse";
                        if (got != expected) return "duration " + duration + ", " + i + "번째 연산 TryUse: 기대 " + expected + ", 결과 " + got;
                    }
                    else
                    {
                        float dt = steps[rng.Next(steps.Length)];
                        c.Tick(dt);
                        if (dt > 0f) remaining = System.Math.Max(0f, remaining - dt);
                        op = "Tick(" + dt + ")";
                    }
                    string e = Check("duration " + duration + ", " + i + "번째 연산 " + op + " 뒤", c, remaining <= 0f, remaining);
                    if (e != null) return e;
                }
            }
            return null;
        });
    }
}

