using TMPro;
using UnityEngine;

// Health is unchanged.

// On the same GameObject as Health. One per enemy, up to 200 in the scene.
public class EnemyNameplate : MonoBehaviour
{
    [SerializeField] private Transform plate;
    [SerializeField] private TMP_Text hpLabel;
    [SerializeField] private float showDistance = 30f;

    private Health _health;      // same GameObject, same lifetime: look up once
    private Transform _player;   // lives until the scene ends: look up once
    private Camera _cam;         // destroyed and recreated by cutscenes: revalidate before use
    private bool _started;

    // A component on the same GameObject can be fetched in Awake.
    private void Awake() => _health = GetComponent<Health>();

    private void OnEnable()
    {
        _health.Changed += RefreshLabel;

        // Damage taken while this object was inactive was missed; resync on re-enable.
        // The first OnEnable is skipped because Health.Awake may not have run yet.
        if (_started) RefreshLabel();
    }

    private void OnDisable() => _health.Changed -= RefreshLabel;

    // Other objects are looked up in Start: one scene search per nameplate, not one per frame.
    private void Start()
    {
        GameObject player = GameObject.Find("Player");
        if (player != null) _player = player.transform;

        _started = true;
        RefreshLabel();
    }

    private void LateUpdate()
    {
        // Unity's == treats a destroyed object as null; ??= and ?. only test the C# reference.
        // isActiveAndEnabled also catches a camera that was disabled instead of destroyed.
        if (_cam == null || !_cam.isActiveAndEnabled) _cam = Camera.main;

        if (_cam == null || _player == null)
        {
            if (plate.gameObject.activeSelf) plate.gameObject.SetActive(false);
            return;
        }

        plate.rotation = _cam.transform.rotation;

        float sqrDistance = (_player.position - transform.position).sqrMagnitude;
        bool visible = sqrDistance <= showDistance * showDistance;
        if (plate.gameObject.activeSelf != visible) plate.gameObject.SetActive(visible);
    }

    // Builds the string only when the HP actually changes.
    private void RefreshLabel() => hpLabel.text = _health.Current + " / " + _health.Max;
}

