using System;

// Plain C#: no UnityEngine types in this file.

// Authored data, shaped like a ScriptableObject asset: created once, shared by every caster,
// and never changed after construction.
public sealed class SkillDefinition
{
    private readonly int[] _damageByLevel;   // private copy; never handed out

    // damageByLevel[0] is the damage at level 1.
    public SkillDefinition(string id, int maxCharges, int[] damageByLevel)
    {
        if (damageByLevel == null) throw new ArgumentNullException(nameof(damageByLevel));
        if (damageByLevel.Length == 0) throw new ArgumentException("at least one level is required", nameof(damageByLevel));
        if (maxCharges < 1) throw new ArgumentOutOfRangeException(nameof(maxCharges), "maxCharges must be >= 1");

        Id = id;
        MaxCharges = maxCharges;
        // Defensive copy: the caller keeps its own array, and later edits to it must not reach us.
        _damageByLevel = (int[])damageByLevel.Clone();
    }

    public string Id { get; }

    public int MaxCharges { get; }

    // Number of entries in damageByLevel.
    public int MaxLevel => _damageByLevel.Length;

    // level is 1-based: 1..MaxLevel.
    public int GetDamage(int level)
    {
        if (level < 1 || level > _damageByLevel.Length)
            throw new ArgumentOutOfRangeException(nameof(level));
        return _damageByLevel[level - 1];
    }
}

// Runtime state: one instance per caster. Reads the definition, never writes to it.
public sealed class SkillState
{
    public SkillState(SkillDefinition definition)
    {
        if (definition == null) throw new ArgumentNullException(nameof(definition));
        Definition = definition;
        Level = 1;
        Charges = definition.MaxCharges;
    }

    public SkillDefinition Definition { get; }

    // Starts at 1.
    public int Level { get; private set; }

    // Starts at Definition.MaxCharges.
    public int Charges { get; private set; }

    // Damage at the current level. Computed, so it can never disagree with Level.
    public int Damage => Definition.GetDamage(Level);

    // Raises Level by one and returns true; returns false at MaxLevel.
    public bool TryLevelUp()
    {
        if (Level >= Definition.MaxLevel) return false;
        Level++;
        return true;
    }

    // Spends one charge and outputs Damage; with no charge left, outputs 0 and returns false.
    public bool TryUse(out int damage)
    {
        if (Charges <= 0)
        {
            damage = 0;
            return false;
        }
        Charges--;
