using System;
using System.Collections.Generic;

// Plain C#: no UnityEngine types in this file.

public readonly struct ItemStack
{
    public ItemStack(string name, int count) { Name = name; Count = count; }
    public string Name { get; }
    public int Count { get; }
}

// Model. Works as intended. Do not change.
public sealed class InventoryModel
{
    private readonly List<ItemStack> _items = new List<ItemStack>();

    // Raised once after every successful Add or Remove.
    public event Action Changed;

    // For tests and leak hunting: true while anything is subscribed to Changed.
    public bool HasSubscribers => Changed != null;

    public int Count => _items.Count;

    public ItemStack Get(int index) => _items[index];

    // Stacks onto an existing entry with the same name, otherwise appends a new slot.
    public void Add(string name, int count)
    {
        if (count <= 0) throw new ArgumentOutOfRangeException(nameof(count));
        int i = IndexOf(name);
        if (i >= 0) _items[i] = new ItemStack(name, _items[i].Count + count);
        else _items.Add(new ItemStack(name, count));
        Changed?.Invoke();
    }

    // Returns false and changes nothing if fewer than count are owned.
    // A stack that reaches 0 is removed and the slots after it shift down.
    public bool Remove(string name, int count)
    {
        if (count <= 0) throw new ArgumentOutOfRangeException(nameof(count));
        int i = IndexOf(name);
        if (i < 0 || _items[i].Count < count) return false;
        if (_items[i].Count == count) _items.RemoveAt(i);
        else _items[i] = new ItemStack(name, _items[i].Count - count);
        Changed?.Invoke();
        return true;
    }

    private int IndexOf(string name)
    {
        for (int i = 0; i < _items.Count; i++)
            if (_items[i].Name == name) return i;
        return -1;
    }
}

// View contract. In the game this is a MonoBehaviour that owns the uGUI widgets;
// in tests it is a fake that records the calls.
public interface IInventoryView
{
    // Raised with the slot index when the player clicks a slot.
    event Action<int> SlotClicked;

    // Replaces all slot labels. The view must read the list during the call and not keep it.
    void ShowSlots(IReadOnlyList<string> labels);

    // index is -1 and detail is "" when nothing is selected.
    void ShowSelection(int index, string detail);
}

public sealed class InventoryPresenter : IDisposable
{
    private readonly InventoryModel _model;
    private readonly IInventoryView _view;
    private readonly List<string> _labels = new List<string>();   // reused on every refresh
    private string _selectedName;   // null = nothing selected
    private bool _disposed;

    public InventoryPresenter(InventoryModel model, IInventoryView view)
    {
        if (model == null) throw new ArgumentNullException(nameof(model));
        if (view == null) throw new ArgumentNullException(nameof(view));
        _model = model;
        _view = view;
        SelectedIndex = -1;

        _model.Changed += OnModelChanged;
        _view.SlotClicked += OnSlotClicked;

        PushSlots();
        PushSelection();
    }

    // Index of the selected slot, or -1.
    public int SelectedIndex { get; private set; }

    // "Potion" for 1, "Potion x12" for 2..999, "Potion x999+" for 1000 and more.
    public static string FormatLabel(ItemStack item)
    {
        if (item.Count <= 1) return item.Name;
        if (item.Count >= 1000) return item.Name + " x999+";
        return item.Name + " x" + item.Count;
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        _model.Changed -= OnModelChanged;
        _view.SlotClicked -= OnSlotClicked;
    }

    private void OnSlotClicked(int index)
    {
        if (index < 0 || index >= _model.Count) return;

        if (index == SelectedIndex)
        {
            _selectedName = null;
            SelectedIndex = -1;
        }
        else
        {
            _selectedName = _model.Get(index).Name;
            SelectedIndex = index;
        }
        PushSelection();   // labels did not change, so ShowSlots is not called
    }

    private void OnModelChanged()
    {
        // The selection follows the item, not the slot number.
        SelectedIndex = -1;
        if (_selectedName != null)
        {
            for (int i = 0; i < _model.Count; i++)
            {
                if (_model.Get(i).Name == _selectedName) { SelectedIndex = i; break; }
            }
            if (SelectedIndex < 0) _selectedName = null;
        }
        PushSlots();
        PushSelection();
    }

    private void PushSlots()
    {
        _labels.Clear();
        for (int i = 0; i < _model.Count; i++)
            _labels.Add(FormatLabel(_model.Get(i)));
        _view.ShowSlots(_labels);
    }

    private void PushSelection()
    {
        if (SelectedIndex < 0)
        {
            _view.ShowSelection(-1, "");
            return;
        }
        ItemStack item = _model.Get(SelectedIndex);
        _view.ShowSelection(SelectedIndex, item.Name + " (" + item.Count + ")");
    }
}

