            if (e != null) return e;
            m.Add("Arrow", 5);
            return Check("사라졌던 Arrow 가 다시 들어와도 선택은 돌아오지 않음", v, p, "Sword|Arrow x5", -1, "");
        });
        Run("dispose-unsubscribes", () =>
        {
            var m = Model3(); var v = new __FakeView();
            var p = new InventoryPresenter(m, v);
            if (!m.HasSubscribers || !v.HasSubscribers) return "생성 뒤 모델 또는 뷰 이벤트를 구독하지 않음";
            v.Click(1);
            p.Dispose();
            if (m.HasSubscribers) return "Dispose 뒤에도 InventoryModel.Changed 구독이 남아 있음";
            if (v.HasSubscribers) return "Dispose 뒤에도 IInventoryView.SlotClicked 구독이 남아 있음";
            m.Add("Potion", 1); v.Click(0);
            string e = Calls("Dispose 뒤의 모델 변경과 클릭은 뷰를 호출하지 않아야 함", v, 1, 2);
            if (e != null) return e;
            p.Dispose();
            return null;
        });
        Run("constructor-null", () =>
        {
            if (!Throws<System.ArgumentNullException>(() => new InventoryPresenter(null, new __FakeView()))) return "model 이 null 인데 ArgumentNullException 이 나지 않음";
            if (!Throws<System.ArgumentNullException>(() => new InventoryPresenter(new InventoryModel(), null))) return "view 가 null 인데 ArgumentNullException 이 나지 않음";
            return null;
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            string[] names = { "A", "B", "C", "D", "E" };
            for (int round = 0; round < 40; round++)
            {
                var m = new InventoryModel(); var v = new __FakeView();
                var p = new InventoryPresenter(m, v);
                string sel = null;
                for (int step = 0; step < 60; step++)
                {
                    int op = rng.Next(3);
                    string what;
                    if (op == 0) { string n = names[rng.Next(5)]; int c = rng.Next(1, 700); m.Add(n, c); what = "Add(" + n + "," + c + ")"; }
                    else if (op == 1) { string n = names[rng.Next(5)]; int c = rng.Next(1, 700); m.Remove(n, c); what = "Remove(" + n + "," + c + ")"; }
                    else
                    {
                        int i = rng.Next(-1, 7); what = "Click(" + i + ")";
                        if (i >= 0 && i < m.Count) sel = m.Get(i).Name == sel ? null : m.Get(i).Name;
                        v.Click(i);
                    }
                    var labels = new System.Collections.Generic.List<string>();
                    int index = -1; string detail = "";
                    for (int i = 0; i < m.Count; i++)
                    {
                        var it = m.Get(i);
                        labels.Add(it.Count <= 1 ? it.Name : it.Count >= 1000 ? it.Name + " x999+" : it.Name + " x" + it.Count);
                        if (it.Name == sel) { index = i; detail = it.Name + " (" + it.Count + ")"; }
                    }
                    if (index < 0) sel = null;
                    string e = Check("round " + round + " step " + step + " " + what + " 뒤", v, p, string.Join("|", labels), index, detail);
                    if (e != null) return e;
                }
                p.Dispose();
                if (m.HasSubscribers || v.HasSubscribers) return "round " + round + ": Dispose 뒤 구독이 남아 있음";
            }
            return null;
        });
    }
}

