using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

// On the Player. Lives as long as the scene. Works as intended. Do not change.
public class PlayerInventory : MonoBehaviour
{
    private readonly List<string> _names = new List<string>();
    private readonly List<int> _counts = new List<int>();

    public event Action Changed;

    public int Count => _names.Count;
    public string GetName(int index) => _names[index];
    public int GetCount(int index) => _counts[index];

    public void Add(string itemName)
    {
        int i = _names.IndexOf(itemName);
        if (i >= 0) _counts[i]++;
        else { _names.Add(itemName); _counts.Add(1); }
        Changed?.Invoke();
    }

    // Uses one item. An emptied slot is removed and the slots after it shift down.
    public void Use(int index)
    {
        if (index < 0 || index >= _names.Count) return;
        _counts[index]--;
        if (_counts[index] == 0) { _names.RemoveAt(index); _counts.RemoveAt(index); }
        Changed?.Invoke();
    }
}

// One per slot widget. The panel owns 20 of these and rebinds them on every refresh.
