using UnityEngine;

// On every enemy.
public class Knockback : MonoBehaviour
{
    [SerializeField] private float speed = 12f;
    [SerializeField] private float duration = 0.25f;

    private Vector3 _direction;
    private float _timeLeft;

    // Called by the projectile that hit this enemy.
    public void Apply(Vector3 direction)
    {
        _direction = direction.normalized;
        _timeLeft = duration;
    }

    private void Update()
    {
        if (_timeLeft <= 0f) return;

        transform.position += _direction * speed * Time.deltaTime;
        _timeLeft -= Time.deltaTime;
    }
}

// On every enemy.
public class EnemySight : MonoBehaviour
{
    [SerializeField] private Transform eye;
    [SerializeField] private float viewDistance = 15f;

    private int _wallMask;

    private void Awake()
    {
        _wallMask = LayerMask.NameToLayer("Wall");
    }

    public bool CanSee(Transform target)
    {
        Vector3 toTarget = target.position - eye.position;
        float distance = toTarget.magnitude;
        if (distance > viewDistance) return false;
        if (distance < 0.01f) return true;

        bool blocked = Physics.Raycast(eye.position, toTarget / distance, distance, _wallMask);
        return !blocked;
    }
}

// On the patrol drone.
public class PatrolDrone : MonoBehaviour
{
    [SerializeField] private Transform[] waypoints;
    [SerializeField] private float speed = 3f;

    private int _next;

    private void Update()
    {
        Vector3 target = waypoints[_next].position;
        transform.position = Vector3.MoveTowards(transform.position, target, speed * Time.deltaTime);
        if (transform.position == target) _next = (_next + 1) % waypoints.Length;
    }
}

// On the alarm zone.
public class AlarmZone : MonoBehaviour
{
    public int AlarmCount { get; private set; }

    private void OnTriggerEnter(Collider other)
    {
        if (other.GetComponent<PatrolDrone>() != null || other.CompareTag("Player"))
            AlarmCount++;
    }
}

