problems.solutionCode:
using System;

// Plain C#: no UnityEngine types. The MonoBehaviour adapter calls Step once per simulation step.
public sealed class JumpAssist
{
    private readonly float _coyoteTime;
    private readonly float _bufferTime;

    // Seconds since the last grounded step / the last press. Infinity means "no record".
    private float _sinceGrounded = float.PositiveInfinity;
    private float _sincePressed = float.PositiveInfinity;

    public JumpAssist(float coyoteTime, float bufferTime)
    {
        if (!(coyoteTime >= 0f)) throw new ArgumentOutOfRangeException(nameof(coyoteTime));
        if (!(bufferTime >= 0f)) throw new ArgumentOutOfRangeException(nameof(bufferTime));
        _coyoteTime = coyoteTime;
        _bufferTime = bufferTime;
    }

    // Returns true when a jump starts on this step.
    public bool Step(float dt, bool grounded, bool jumpPressed)
    {
        // 1. Age both records by this step's length.
        _sinceGrounded += dt;
        _sincePressed += dt;

        // 2. This step's inputs reset their record to "just now".
        if (grounded) _sinceGrounded = 0f;
        if (jumpPressed) _sincePressed = 0f;

        // 3. Jump only while both records are inside their windows.
        if (_sinceGrounded <= _coyoteTime && _sincePressed <= _bufferTime)
        {
            // Consume both: one press gives one jump, and no coyote jump after a real jump.
            _sinceGrounded = float.PositiveInfinity;
            _sincePressed = float.PositiveInfinity;
            return true;
        }

        return false;
    }
}

