{{USER_CODE}}

public static class __Judge
{
    const float T = 1f / 64f; // exactly representable, so window boundaries are exact

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // script: one char per step. G=지면, g=지면+점프 입력, A=공중, a=공중+점프 입력
    // expected: same length, J=이 스텝에 점프 시작, .=점프 없음
    static string Play(float coyote, float buffer, string script, string expected)
    {
        var j = new JumpAssist(coyote, buffer);
        var got = new System.Text.StringBuilder();
        for (int i = 0; i < script.Length; i++)
        {
            char c = script[i];
            bool grounded = c == 'G' || c == 'g';
            bool pressed = c == 'g' || c == 'a';
            got.Append(j.Step(T, grounded, pressed) ? 'J' : '.');
        }
        if (got.ToString() == expected) return null;
        return "coyote " + (coyote / T) + "스텝, buffer " + (buffer / T) + "스텝, 입력 " + script + " → 기대 " + expected + ", 결과 " + got;
    }

    static bool Throws(float c, float b)
    {
        try { new JumpAssist(c, b); return false; }
        catch (System.ArgumentOutOfRangeException) { return true; }
    }

    public static void Main()
    {
        Run("ground-jump", () =>
            Play(4 * T, 4 * T, "GGgGG", "..J..") ?? Play(0f, 0f, "GgAAGg", ".J...J"));
        Run("no-jump-without-press", () =>
            Play(4 * T, 4 * T, "GGGAAAAGG", ".........") ?? Play(4 * T, 4 * T, "AAaAAAAAA", "........."));
        Run("coyote-window", () =>
            Play(3 * T, 0f, "GAAa", "...J") ?? Play(3 * T, 0f, "GAAAa", "....."));
        Run("buffer-window", () =>
            Play(0f, 3 * T, "AaAAG", "....J") ?? Play(0f, 3 * T, "AaAAAG", "......"));
        Run("no-air-jump-after-jump", () =>
            Play(4 * T, 0f, "GgAaAa", ".J....") ?? Play(4 * T, 4 * T, "gAaAAAAA", "J......."));
        Run("one-press-one-jump", () =>
            Play(0f, 4 * T, "AaGGGG", "..J...") ?? Play(2 * T, 4 * T, "GgGAAG", ".J...."));
        Run("invalid-arguments", () =>
        {
            if (!Throws(-0.1f, 0.1f)) return "coyoteTime -0.1 에서 ArgumentOutOfRangeException 이 나지 않음";
            if (!Throws(0.1f, -0.1f)) return "bufferTime -0.1 에서 ArgumentOutOfRangeException 이 나지 않음";
            if (Throws(0f, 0f)) return "coyoteTime 0, bufferTime 0 은 허용되어야 함";
            return null;
        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 300; round++)
            {
                int cSteps = rng.Next(0, 5), bSteps = rng.Next(0, 5);
                var j = new JumpAssist(cSteps * T, bSteps * T);
                // 참조 구현: 정수 스텝 수로 센다 (dt 가 T 의 1~3배).
                long sinceG = long.MaxValue / 2, sinceP = long.MaxValue / 2;
                bool grounded = true;
                var log = new System.Text.StringBuilder();
                for (int i = 0; i < 40; i++)
                {
                    int k = rng.Next(1, 4);
                    if (rng.Next(4) == 0) grounded = !grounded;
                    bool pressed = rng.Next(3) == 0;
                    sinceG += k; sinceP += k;
                    if (grounded) sinceG = 0;
                    if (pressed) sinceP = 0;
                    bool expected = sinceG <= cSteps && sinceP <= bSteps;
                    if (expected) { sinceG = long.MaxValue / 2; sinceP = long.MaxValue / 2; }
                    bool got = j.Step(k * T, grounded, pressed);
                    log.Append("(dt " + k + "T," + (grounded ? "지면" : "공중") + (pressed ? ",입력" : "") + ")");
                    if (got != expected)
                        return "coyote " + cSteps + "T, buffer " + bSteps + "T, " + (i + 1) + "번째 스텝: 기대 " + expected + ", 결과 " + got + " / 직전 4스텝 포함 로그 끝: " + log.ToString().Substring(System.Math.Max(0, log.Length - 60));
                }
            }
            return null;
        });
    }
}

