        op.allowSceneActivation = false;                                // (a)

        while (!op.isDone)                                              // (b)
        {
            progressBar.value = op.progress;
            yield return null;
        }

        pressKeyLabel.SetActive(true);
        while (!Input.GetKeyDown(KeyCode.Space)) yield return null;
