problems.solutionCode:
// ---- Answer key ----
// Q1 The bar stops at 0.9 and the label never appears.
//    With allowSceneActivation == false, Unity stops progress at 0.9 and isDone remains false,
//    so "while (!op.isDone)" at (b) never ends and the line that shows the label is never reached.
//    Fix: treat progress >= 0.9 as "ready", then set allowSceneActivation = true on the key press.
// Q2 (1) DontDestroyOnLoad only works for root GameObjects or components on root GameObjects.
//        "Managers/Bgm" is a child, so the call at (c) is outside what the API supports.
//    (2) Every load of the Title scene creates the scene's own Bgm object again, while the preserved
//        one is still alive. The script has to remove the duplicate itself.
// Q3 (d) The Dungeon scene. After an additive load the first scene is still the active scene, and the
//        active scene is the target for GameObjects instantiated by scripts.
//    (e) The GameObjects of ShopUI are destroyed and the scene is removed from the SceneManager,
//        but assets are not unloaded. Call Resources.UnloadUnusedAssets to free asset memory.

using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

// In the Title scene.
public class LoadingScreen : MonoBehaviour
{
    private const float ReadyProgress = 0.9f;   // where progress stops while activation is not allowed

    [SerializeField] private Slider progressBar;        // 0..1
    [SerializeField] private GameObject pressKeyLabel;  // "Press Space"

    public void Begin(string sceneName)
    {
        StartCoroutine(LoadRoutine(sceneName));
    }

    private IEnumerator LoadRoutine(string sceneName)
    {
        AsyncOperation op = SceneManager.LoadSceneAsync(sceneName, LoadSceneMode.Single);
        op.allowSceneActivation = false;

        while (op.progress < ReadyProgress)
        {
            progressBar.value = op.progress / ReadyProgress;   // show 0..0.9 as 0..100 %
            yield return null;
        }

        progressBar.value = 1f;
        pressKeyLabel.SetActive(true);
        while (!Input.GetKeyDown(KeyCode.Space)) yield return null;

        // From here isDone can complete: the new scene activates and the Title scene is unloaded.
        op.allowSceneActivation = true;
    }
}

// In the Title scene, on a ROOT GameObject "Bgm" (moved out of "Managers" in the Hierarchy).
public class BgmPlayer : MonoBehaviour
{
    private static BgmPlayer _instance;

    private void Awake()
    {
        if (_instance != null && _instance != this)
        {
            Destroy(gameObject);        // the Title scene was loaded again: keep the first one
            return;
        }

        _instance = this;
        DontDestroyOnLoad(gameObject);
    }
}

