public class ShopOpener : MonoBehaviour
{
    [SerializeField] private GameObject shopkeeperPrefab;

    public IEnumerator OpenShop()
    {
        yield return SceneManager.LoadSceneAsync("ShopUI", LoadSceneMode.Additive);

        // New GameObjects are created in the active scene (still Dungeon). Move the shopkeeper into
        // ShopUI so that it is destroyed together with that scene in CloseShop.
        GameObject shopkeeper = Instantiate(shopkeeperPrefab);
        SceneManager.MoveGameObjectToScene(shopkeeper, SceneManager.GetSceneByName("ShopUI"));
    }

    public IEnumerator CloseShop()
    {
        yield return SceneManager.UnloadSceneAsync("ShopUI");
        yield return Resources.UnloadUnusedAssets();    // unloading a scene does not unload its assets
    }
}

