using System;
using System.Collections.Generic;

// Plain C#: no UnityEngine types.
// Lives as long as the game (owned by a bootstrap object kept with DontDestroyOnLoad).
public sealed class EventChannel<T>
{
    private sealed class Subscription : IDisposable
    {
        private EventChannel<T> _owner;
        public Action<T> Handler;

        public Subscription(EventChannel<T> owner, Action<T> handler)
        {
            _owner = owner;
            Handler = handler;
        }

        public bool IsActive => _owner != null;

        public void Dispose()
        {
            EventChannel<T> owner = _owner;
            if (owner == null) return;      // second and later calls do nothing
            _owner = null;
            Handler = null;                 // drop the handler (and whatever it captured) right away
            owner.OnSubscriptionDisposed();
        }
    }

    // Subscription order. May contain disposed entries until the next compaction.
    private readonly List<Subscription> _subs = new List<Subscription>();
    private int _activeCount;
    private int _publishDepth;

    public int SubscriberCount => _activeCount;

    public IDisposable Subscribe(Action<T> handler)
    {
        if (handler == null) throw new ArgumentNullException(nameof(handler));
        var subscription = new Subscription(this, handler);
        _subs.Add(subscription);
        _activeCount++;
        return subscription;
    }

    public void Publish(T value)
    {
        // Handlers subscribed while this call runs are appended after 'count' and are not called now.
        int count = _subs.Count;
        _publishDepth++;
        try
        {
            for (int i = 0; i < count; i++)
            {
                Subscription s = _subs[i];
                if (s.IsActive) s.Handler(value);   // skips entries disposed earlier in this same call
            }
        }
        finally
        {
            _publishDepth--;
            CompactIfWorthIt();
        }
    }

    private void OnSubscriptionDisposed()
    {
        _activeCount--;
        CompactIfWorthIt();
    }

    // The list is never shrunk while a Publish loop is indexing it. Outside of Publish, dead entries
    // are removed once they make up at least half of the list, so a Dispose is amortized O(1).
    private void CompactIfWorthIt()
    {
        if (_publishDepth > 0) return;
        int dead = _subs.Count - _activeCount;
        if (dead == 0 || dead * 2 < _subs.Count) return;

        int write = 0;
        for (int read = 0; read < _subs.Count; read++)
        {
            Subscription s = _subs[read];
            if (s.IsActive) _subs[write++] = s;
        }
        _subs.RemoveRange(write, _subs.Count - write);
    }
}

// One bag per scene (or per screen). Disposing it ends every subscription that was added to it.
public sealed class SubscriptionBag : IDisposable
{
    private List<IDisposable> _items = new List<IDisposable>();
    private bool _disposed;

    public bool IsDisposed => _disposed;
    public int Count => _disposed ? 0 : _items.Count;

    public void Add(IDisposable subscription)
    {
        if (subscription == null) throw new ArgumentNullException(nameof(subscription));
        if (_disposed)
        {
            // The scope is already over: do not keep a subscription that nobody would ever end.
            subscription.Dispose();
            return;
        }
        _items.Add(subscription);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;               // set first: an Add made from inside a Dispose below is disposed at once
        List<IDisposable> items = _items;
        _items = null;
        for (int i = 0; i < items.Count; i++) items[i].Dispose();
    }
}

