        });
        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 60; round++)
            {
                var ch = new EventChannel<int>();
                var log = new System.Text.StringBuilder();
                var expected = new System.Text.StringBuilder();
                var tokens = new System.Collections.Generic.List<System.IDisposable>();
                var alive = new System.Collections.Generic.List<bool>();
                var bag = new SubscriptionBag();
                var inBag = new System.Collections.Generic.List<bool>();
                for (int step = 0; step < 80; step++)
                {
                    int op = rng.Next(10);
                    if (op < 4)
                    {
                        int id = tokens.Count;
                        System.IDisposable t = ch.Subscribe(v => log.Append(id).Append(','));
                        bool toBag = rng.Next(3) == 0;
                        bool bagWasDisposed = bag.IsDisposed;
                        if (toBag) bag.Add(t);
                        tokens.Add(t); alive.Add(!(toBag && bagWasDisposed)); inBag.Add(toBag);
                    }
                    else if (op < 6 && tokens.Count > 0)
                    {
                        int id = rng.Next(tokens.Count);
                        tokens[id].Dispose(); alive[id] = false;
                    }
                    else if (op == 6 && rng.Next(4) == 0)
                    {
                        bag.Dispose();
                        for (int i = 0; i < alive.Count; i++) if (inBag[i]) alive[i] = false;
                    }
                    else
                    {
                        ch.Publish(0); log.Append(';');
                        for (int i = 0; i < alive.Count; i++) if (alive[i]) expected.Append(i).Append(',');
                        expected.Append(';');
                    }
                    int count = 0;
                    for (int i = 0; i < alive.Count; i++) if (alive[i]) count++;
                    if (ch.SubscriberCount != count) return "라운드 " + round + ", " + step + "번째 연산 뒤 SubscriberCount 기대 " + count + ", 결과 " + ch.SubscriberCount;
                    if (log.ToString() != expected.ToString()) return "라운드 " + round + ", " + step + "번째 연산 뒤 호출 로그가 참조 구현과 다름 (구독 번호 순서, ';' 는 Publish 경계)";
                }
            }
            return null;
        });
    }
}

