using System;
using System.Collections.Generic;

// ===== 주어진 코드: 엔진 없이 수명 규칙만 시험하려고 Addressables 를 흉내 낸 가짜. 바꾸지 마세요. =====

public enum LoadStatus { None, Succeeded, Failed }

// 가짜 에셋(스프라이트). 같은 키의 성공한 핸들이 하나라도 살아 있는 동안 IsLoaded 가 true 다.
public sealed class FakeSprite
{
    public FakeSprite(string key) { Key = key; }
    public string Key { get; }
    public bool IsLoaded { get; internal set; }
    public int UnloadCount { get; internal set; }
}

// 로드 작업 하나. 핸들(구조체)의 복사본은 모두 이 객체 하나를 가리킨다.
internal sealed class LoadOperation
{
    internal LoadOperation(string key) { Key = key; }
    internal string Key;
    internal bool Done;
    internal bool Released;
    internal LoadStatus Status;
    internal FakeSprite Sprite;
    internal Action<AssetHandle> Completed;
}

// AsyncOperationHandle<Sprite> 를 흉내 낸 핸들.
// 해제된 핸들에서는 IsValid(), Key, Equals 외의 멤버를 쓰면 InvalidOperationException 이 난다.
public readonly struct AssetHandle : IEquatable<AssetHandle>
{
    private readonly LoadOperation _op;
    internal AssetHandle(LoadOperation op) { _op = op; }
    internal LoadOperation Operation => _op;

    public bool IsValid() => _op != null && !_op.Released;
    public string Key => _op?.Key;
    public bool IsDone => Op().Done;
    public LoadStatus Status => Op().Status;
    public FakeSprite Result => Op().Done && Op().Status == LoadStatus.Succeeded ? Op().Sprite : null;

    public event Action<AssetHandle> Completed
    {
        add { Op().Completed += value; }
        remove { Op().Completed -= value; }
    }

    private LoadOperation Op()
    {
        if (!IsValid()) throw new InvalidOperationException("해제되었거나 비어 있는 핸들을 사용했습니다: " + (Key ?? "default"));
        return _op;
    }

    public bool Equals(AssetHandle other) => ReferenceEquals(_op, other._op);
    public override bool Equals(object obj) => obj is AssetHandle other && Equals(other);
    public override int GetHashCode() => _op == null ? 0 : _op.GetHashCode();
}

public interface IAssetLoader
{
    AssetHandle LoadAsync(string key);
    void Release(AssetHandle handle);
}

public sealed class FakeAssetLoader : IAssetLoader
{
    private readonly List<LoadOperation> _pending = new List<LoadOperation>();
    private readonly Dictionary<string, FakeSprite> _sprites = new Dictionary<string, FakeSprite>();
    private readonly Dictionary<string, int> _refCounts = new Dictionary<string, int>();

    // 만들어졌지만 아직 해제되지 않은 핸들 수(실패한 핸들, 완료 전 핸들 포함).
    public int LiveHandleCount { get; private set; }
    public int PendingCount => _pending.Count;

    public AssetHandle LoadAsync(string key)
    {
        var op = new LoadOperation(key);
        _pending.Add(op);
        LiveHandleCount++;
        return new AssetHandle(op);
    }

    // 완료된, 아직 해제하지 않은 핸들만 해제할 수 있다.
    public void Release(AssetHandle handle)
    {
        LoadOperation op = handle.Operation;
        if (op == null) throw new InvalidOperationException("default 핸들을 해제하려 했습니다.");
        if (op.Released) throw new InvalidOperationException("이미 해제한 핸들을 다시 해제했습니다: " + op.Key);
        if (!op.Done) throw new InvalidOperationException("완료되지 않은 핸들을 해제했습니다(이 문제의 규칙 위반): " + op.Key);
        op.Released = true;
        LiveHandleCount--;
        if (op.Status == LoadStatus.Succeeded && --_refCounts[op.Key] == 0)
        {
            FakeSprite sprite = _sprites[op.Key];
            sprite.IsLoaded = false;
            sprite.UnloadCount++;
        }
    }

    // 엔진(채점기)이 부른다. key 로 요청된 작업 중 가장 오래된 것을 완료하고 Completed 를 동기적으로 호출한다.
    public void Complete(string key, bool succeeded)
    {
        int index = _pending.FindIndex(o => o.Key == key);
        if (index < 0) throw new InvalidOperationException("대기 중인 요청이 없습니다: " + key);
        LoadOperation op = _pending[index];
        _pending.RemoveAt(index);
        op.Done = true;
        op.Status = succeeded ? LoadStatus.Succeeded : LoadStatus.Failed;
        if (succeeded)
        {
            if (!_sprites.TryGetValue(key, out FakeSprite sprite)) _sprites[key] = sprite = new FakeSprite(key);
            _refCounts[key] = (_refCounts.TryGetValue(key, out int count) ? count : 0) + 1;
            sprite.IsLoaded = true;
            op.Sprite = sprite;
        }
        Action<AssetHandle> callbacks = op.Completed;
        op.Completed = null;
        callbacks?.Invoke(new AssetHandle(op));
    }

    public FakeSprite PeekSprite(string key) => _sprites.TryGetValue(key, out FakeSprite sprite) ? sprite : null;
}

// 미리보기 패널의 화면. ShowPortrait 는 지금 보이는 초상화에서 새 초상화로 크로스페이드한다(이전 스프라이트를 읽는다).
public interface ISkinPreviewView
{
    void ShowPortrait(FakeSprite sprite);
    void ShowError(string key);
    void Clear();
}

// ===== 고칠 코드 =====

public sealed class SkinPreviewPresenter : IDisposable
{
    private readonly IAssetLoader _loader;
    private readonly ISkinPreviewView _view;
    private readonly List<AssetHandle> _requested = new List<AssetHandle>();
    private AssetHandle _shown;    // 지금 화면에 보이는 초상화
    private AssetHandle _latest;   // 가장 최근 요청
    private bool _open;

    public SkinPreviewPresenter(IAssetLoader loader, ISkinPreviewView view)
    {
        _loader = loader;
        _view = view;
    }

    public void Show(string key)
    {
        _open = true;
        if (_shown.IsValid()) _loader.Release(_shown);
        _latest = _loader.LoadAsync(key);
        _requested.Add(_latest);
        _latest.Completed += OnLoaded;
    }

    private void OnLoaded(AssetHandle handle)
    {
        if (!_open || !handle.Equals(_latest)) return;
        if (handle.Status == LoadStatus.Failed)
        {
            _view.ShowError(handle.Key);
            _loader.Release(handle);
            return;
        }
        _shown = handle;
        _view.ShowPortrait(handle.Result);
    }

    public void Close()
    {
        if (!_open) return;
        _open = false;
        _view.Clear();
        if (_shown.IsValid()) _loader.Release(_shown);
    }

    public void Dispose()
    {
        Close();
        foreach (AssetHandle handle in _requested) _loader.Release(handle);
        _requested.Clear();
    }
}

