public static class __Judge
{
    // 크로스페이드하는 화면을 흉내 낸다: 띄우는 순간 이전 초상화가 아직 로드되어 있어야 한다.
    sealed class View : ISkinPreviewView
    {
        public FakeSprite Shown; public string Violation; public string LastError; public int Calls, Portraits;
        void Note(string v) { if (Violation == null) Violation = v; }
        public void Check() { if (Shown != null && !Shown.IsLoaded) Note("화면에 보이는 '" + Shown.Key + "' 가 이미 해제됨"); }
        public void ShowPortrait(FakeSprite s)
        {
            Calls++; Portraits++;
            if (s == null || !s.IsLoaded) Note("해제되었거나 null 인 스프라이트를 ShowPortrait 에 넘김");
            if (Shown != null && !Shown.IsLoaded) Note("새 초상화를 띄우기 전에 화면의 '" + Shown.Key + "' 를 해제함(크로스페이드가 해제된 스프라이트를 읽음)");
            Shown = s;
        }
        public void ShowError(string key) { Calls++; LastError = key; Check(); }
        public void Clear() { Calls++; Shown = null; }
    }

    // 프레젠터의 Release 호출을 지켜본다: 규칙(F3)을 어긴 호출은 프레젠터가 예외를 삼켜도 기록에 남는다.
    sealed class Spy : IAssetLoader
    {
        public readonly FakeAssetLoader Inner = new FakeAssetLoader();
        public string Bad;
        public AssetHandle LoadAsync(string key) => Inner.LoadAsync(key);
        public void Release(AssetHandle h)
        {
            try { Inner.Release(h); }
            catch (System.InvalidOperationException e) { if (Bad == null) Bad = e.Message; throw; }
        }
    }

    sealed class Ctx
    {
        public readonly Spy S = new Spy();
        public FakeAssetLoader L => S.Inner;
        public readonly View V = new View();
        public readonly SkinPreviewPresenter P;
        public Ctx() { P = new SkinPreviewPresenter(S, V); }
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 " + e.GetType().Name + ": " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 단계마다: 화면 불변식, 살아 있는 핸들 수(대기 중 요청 + 보이는 초상화), 화면의 초상화.
    static string Expect(Ctx c, string step, int live, string shownKey)
    {
        c.V.Check();
        if (c.S.Bad != null) return step + " 뒤: 규칙을 어긴 Release 호출이 있었음(예외를 삼켰더라도 실패) — " + c.S.Bad;
        if (c.V.Violation != null) return step + " 뒤: " + c.V.Violation;
        if (c.L.LiveHandleCount != live) return step + " 뒤 살아 있는 핸들 기대 " + live + " / 결과 " + c.L.LiveHandleCount;
        string shown = c.V.Shown == null ? "없음" : c.V.Shown.Key;
        return shown == (shownKey ?? "없음") ? null : step + " 뒤 화면의 초상화 기대 " + (shownKey ?? "없음") + " / 결과 " + shown;
    }

    public static void Main()
    {
        Run("switch-new-then-release-old", () =>
        {
            var c = new Ctx();
            c.P.Show("knight"); c.L.Complete("knight", true);
            string e = Expect(c, "Show(knight) → 완료", 1, "knight");
            if (e == null) { c.P.Show("mage"); e = Expect(c, "Show(knight) → 완료 → Show(mage)", 2, "knight"); }
            if (e == null) { c.L.Complete("mage", true); e = Expect(c, "… → mage 완료", 1, "mage"); }
            if (e == null && c.L.PeekSprite("knight").IsLoaded) e = "mage 를 띄운 뒤에도 knight 가 해제되지 않음";
            return e;
        });

        Run("same-key-no-churn", () =>
        {
            var c = new Ctx();
            c.P.Show("knight"); c.L.Complete("knight", true);
            c.P.Show("knight");
            string e = Expect(c, "knight 를 띄운 채 Show(knight)", 2, "knight");
            if (e == null) { c.L.Complete("knight", true); e = Expect(c, "… → 두 번째 knight 완료", 1, "knight"); }
            int unloads = c.L.PeekSprite("knight").UnloadCount;
            return e ?? (unloads == 0 ? null : "같은 스킨을 다시 보는 동안 knight 가 언로드됨(UnloadCount " + unloads + ")");
        });

        Run("stale-response-released", () =>
        {
            var c = new Ctx();
            c.P.Show("knight"); c.P.Show("mage"); c.L.Complete("knight", true);
            string e = Expect(c, "Show(knight) → Show(mage) → knight 먼저 완료", 1, null);
            if (e == null) { c.L.Complete("mage", true); e = Expect(c, "… → mage 완료", 1, "mage"); }
            if (e == null) { c.P.Show("rogue"); c.P.Show("knight"); c.L.Complete("knight", true); e = Expect(c, "… → Show(rogue) → Show(knight) → knight 완료", 2, "knight"); }
            if (e == null) { c.L.Complete("rogue", true); e = Expect(c, "… → 늦게 온 rogue 완료", 1, "knight"); }
            return e;
        });

        Run("close-while-loading", () =>
        {
            var c = new Ctx();
            c.P.Show("knight"); c.P.Close();
            string e = Expect(c, "Show(knight) → Close()", 1, null);
            if (e == null) { c.L.Complete("knight", true); e = Expect(c, "Show(knight) → Close() → knight 완료", 0, null); }
            return e ?? (c.V.Portraits == 0 ? null : "닫은 뒤에 완료된 요청을 화면에 띄움");
        });

        Run("failed-load-then-dispose", () =>
        {
            var c = new Ctx();
            c.P.Show("knight"); c.L.Complete("knight", false);
            if (c.V.LastError != "knight") return "실패한 로드에 ShowError(knight) 를 부르지 않음";
            string e = Expect(c, "Show(knight) → 실패", 0, null);
            if (e == null) { c.P.Dispose(); e = Expect(c, "Show(knight) → 실패 → Dispose()", 0, null); }
            return e;
        });

        Run("close-then-dispose", () =>
        {
            var c = new Ctx();
            c.P.Show("knight"); c.L.Complete("knight", true); c.P.Close(); c.P.Close();
            string e = Expect(c, "Show(knight) → 완료 → Close() → Close()", 0, null);
            if (e == null && c.L.PeekSprite("knight").IsLoaded) e = "Close 뒤에도 knight 가 해제되지 않음";
            if (e == null) { c.P.Dispose(); e = Expect(c, "… → Dispose()", 0, null); }
            return e;
        });

        Run("dispose-while-loading", () =>
        {
            var c = new Ctx();
            c.P.Show("knight"); c.L.Complete("knight", true); c.P.Show("mage"); c.P.Dispose();
            string e = Expect(c, "Show(knight) → 완료 → Show(mage) → Dispose()", 1, null);
            int calls = c.V.Calls;
            if (e == null) { c.L.Complete("mage", true); e = Expect(c, "… → Dispose 뒤 mage 완료", 0, null); }
            return e ?? (c.V.Calls == calls ? null : "Dispose 뒤에 화면 메서드를 호출함");
        });

        Run("random-vs-reference", () =>
        {
            uint s = 20261122u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            string[] keys = { "knight", "mage", "rogue" };
            for (int t = 0; t < 300; t++)
            {
                var c = new Ctx();
                var pending = new System.Collections.Generic.List<(int id, string key)>();
                int nextId = 0, latest = -1; bool open = false; string shown = null;
                var log = new System.Text.StringBuilder();
                for (int step = 0; step < 25; step++)
                {
                    int op = rnd(10);
                    if (op < 4) { string k = keys[rnd(3)]; c.P.Show(k); open = true; pending.Add((nextId, k)); latest = nextId++; log.Append("Show(" + k + ") "); }
                    else if (op < 9 && pending.Count > 0)
                    {
                        string k = pending[rnd(pending.Count)].key; bool ok = rnd(4) != 0;
                        int idx = pending.FindIndex(x => x.key == k); var item = pending[idx]; pending.RemoveAt(idx);
                        c.L.Complete(k, ok); log.Append(k + (ok ? "완료 " : "실패 "));
                        if (open && item.id == latest) { latest = -1; if (ok) shown = k; }
                    }
                    else { c.P.Close(); open = false; latest = -1; shown = null; log.Append("Close() "); }
                    string e = Expect(c, "무작위 " + t + "번 [" + log.ToString().TrimEnd() + "]", pending.Count + (shown != null ? 1 : 0), shown);
                    if (e != null) return e;
                }
                c.P.Dispose();
                int calls = c.V.Calls;
                while (pending.Count > 0) { string k = pending[0].key; pending.RemoveAt(0); c.L.Complete(k, true); }
                string end = Expect(c, "무작위 " + t + "번 [" + log.ToString().TrimEnd() + "] → Dispose() → 남은 요청 완료", 0, null);
                if (end != null) return end;
                if (c.V.Calls != calls) return "무작위 " + t + "번: Dispose 뒤에 화면 메서드를 호출함";
            }
            return null;
        });
    }
}

