    }
    public SaveLoadStatus Status { get; }
    public int SourceVersion { get; }   // 파일에 적힌(또는 없어서 1 로 본) 버전. Corrupt 이면 0.
    public SaveData Data { get; }       // Loaded, Migrated 일 때만 null 이 아니다.
