}

// ===== 구현 =====

// 각 단계는 바로 다음 버전만 안다. v1 파일은 V1ToV2 → V2ToV3 을 차례로 거친다.
public static class SaveMigrations
{
    // v1 → v2: items(문자열 배열) → inventory([{ "id", "count" }]). version 을 2 로 쓴다.
    public static JsonObject V1ToV2(JsonObject doc)
    {
        var inventory = new JsonArray();
        JsonNode items = doc["items"];
        if (items != null)                                   // 없거나 null 이면 빈 인벤토리
        {
            if (!(items is JsonArray array)) throw new SaveFormatException("items 는 배열이어야 합니다.");
            var slotOf = new Dictionary<string, int>(StringComparer.Ordinal);   // id → inventory 의 위치
            var counts = new List<int>();
            var ids = new List<string>();
            foreach (JsonNode item in array)
            {
                if (!(item is JsonValue value) || !value.TryGetValue(out string id))
                    throw new SaveFormatException("items 의 원소는 문자열이어야 합니다.");
                if (slotOf.TryGetValue(id, out int slot)) counts[slot]++;
                else { slotOf.Add(id, ids.Count); ids.Add(id); counts.Add(1); }   // 처음 나온 순서를 지킨다
            }
            for (int i = 0; i < ids.Count; i++)
                inventory.Add(new JsonObject { ["id"] = ids[i], ["count"] = counts[i] });
        }
        doc.Remove("items");
        doc["inventory"] = inventory;
        doc["version"] = 2;
        return doc;
    }

    // v2 → v3: gold → wallet { "gold", "gems": 0 }. version 을 3 으로 쓴다.
    public static JsonObject V2ToV3(JsonObject doc)
    {
        int gold = SaveLoader.ReadInt(doc, "gold", 0, int.MinValue, int.MaxValue);   // 범위는 읽기 단계에서 검사한다
        doc.Remove("gold");
        doc["wallet"] = new JsonObject { ["gold"] = gold, ["gems"] = 0 };
        doc["version"] = 3;
        return doc;
    }
}

public static class SaveLoader
{
    public const int CurrentVersion = 3;

    // Steps[v] 는 v → v + 1 단계. 열거하지 않고 버전 번호로 찾는다.
    private static readonly Func<JsonObject, JsonObject>[] Steps = { null, SaveMigrations.V1ToV2, SaveMigrations.V2ToV3 };

    public static SaveLoadResult Load(string json)
    {
        if (json == null) return Corrupt();
        try
        {
            if (!(JsonNode.Parse(json) is JsonObject doc)) return Corrupt();   // 루트는 객체여야 한다
            int source = ReadVersion(doc);
            if (source > CurrentVersion)                                        // 모르는 미래 버전: 해석하지도 고치지도 않는다
                return new SaveLoadResult(SaveLoadStatus.FutureVersion, source, null);
            for (int v = source; v < CurrentVersion; v++) doc = Steps[v](doc);  // 버전 순서대로 한 번씩
            SaveData data = ToSaveData(doc);
            return new SaveLoadResult(source == CurrentVersion ? SaveLoadStatus.Loaded : SaveLoadStatus.Migrated, source, data);
        }
        catch (JsonException) { return Corrupt(); }          // JSON 문법 오류
        catch (SaveFormatException) { return Corrupt(); }    // 형식 규칙 위반
    }

    private static SaveLoadResult Corrupt() => new SaveLoadResult(SaveLoadStatus.Corrupt, 0, null);

    // 출시판(v1)은 version 을 쓰지 않았으므로 없거나 null 이면 1 이다.
    private static int ReadVersion(JsonObject doc)
    {
        JsonNode node = doc["version"];
        if (node == null) return 1;
        if (node is JsonValue value && value.TryGetValue(out int version) && version >= 1) return version;
        throw new SaveFormatException("version 은 1 이상의 정수여야 합니다.");
    }

    // v3 문서 → SaveData. 필드가 없거나 null 일 때만 기본값을 쓰고, 있으면 0 이어도 그 값을 쓴다.
    private static SaveData ToSaveData(JsonObject doc)
    {
        var data = new SaveData();
        JsonObject wallet = ReadObject(doc, "wallet");
        if (wallet != null)
        {
            data.Gold = ReadInt(wallet, "gold", data.Gold, 0, int.MaxValue);
            data.Gems = ReadInt(wallet, "gems", data.Gems, 0, int.MaxValue);
        }
        JsonNode inventory = doc["inventory"];
        if (inventory != null)
        {
            if (!(inventory is JsonArray array)) throw new SaveFormatException("inventory 는 배열이어야 합니다.");
            foreach (JsonNode entry in array)
            {
                if (!(entry is JsonObject stack)) throw new SaveFormatException("inventory 의 원소는 객체여야 합니다.");
                if (!(stack["id"] is JsonValue idValue) || !idValue.TryGetValue(out string id) || id.Length == 0)
                    throw new SaveFormatException("id 는 비어 있지 않은 문자열이어야 합니다.");
                if (stack["count"] == null) throw new SaveFormatException("count 가 없습니다.");
                data.Inventory.Add(new ItemStack(id, ReadInt(stack, "count", 0, 1, int.MaxValue)));
            }
        }
        JsonObject settings = ReadObject(doc, "settings");
        if (settings != null) data.BgmVolume = ReadInt(settings, "bgmVolume", data.BgmVolume, 0, 100);
        return data;
    }

    private static JsonObject ReadObject(JsonObject parent, string name)
    {
        JsonNode node = parent[name];
        if (node == null) return null;                       // 없음 또는 null
        return node as JsonObject ?? throw new SaveFormatException(name + " 은 객체여야 합니다.");
    }

    // 없거나 null 이면 fallback, 있으면 [min, max] 범위의 JSON 정수여야 한다.
    internal static int ReadInt(JsonObject parent, string name, int fallback, int min, int max)
    {
        JsonNode node = parent[name];
        if (node == null) return fallback;
        if (node is JsonValue value && value.TryGetValue(out int result) && result >= min && result <= max) return result;
        throw new SaveFormatException(name + " 은 " + min + " ~ " + max + " 범위의 정수여야 합니다.");
    }

    // 주어진 코드: 현재 형식(버전 3)으로 쓴다.
    public static string Save(SaveData data)
    {
        var inventory = new JsonArray();
        foreach (ItemStack stack in data.Inventory)
            inventory.Add(new JsonObject { ["id"] = stack.Id, ["count"] = stack.Count });
        var root = new JsonObject
        {
            ["version"] = CurrentVersion,
            ["wallet"] = new JsonObject { ["gold"] = data.Gold, ["gems"] = data.Gems },
            ["inventory"] = inventory,
            ["settings"] = new JsonObject { ["bgmVolume"] = data.BgmVolume },
        };
        return root.ToJsonString();
    }
}

