public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 " + e.GetType().Name + ": " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Fmt(SaveData d)
    {
        if (d == null) return "null";
        var sb = new System.Text.StringBuilder();
        sb.Append("gold=").Append(d.Gold).Append(" gems=").Append(d.Gems).Append(" bgm=").Append(d.BgmVolume).Append(" inv=[");
        for (int i = 0; i < d.Inventory.Count; i++) sb.Append(i > 0 ? "," : "").Append(d.Inventory[i].Id).Append('x').Append(d.Inventory[i].Count);
        return sb.Append(']').ToString();
    }

    static SaveData Data(int gold, int gems, int bgm, params (string id, int count)[] inv)
    {
        var d = new SaveData { Gold = gold, Gems = gems, BgmVolume = bgm };
        foreach (var s in inv) d.Inventory.Add(new ItemStack(s.id, s.count));
        return d;
    }

    // Load 결과가 기대한 상태 · 원래 버전 · 데이터인지 확인한다.
    static string Check(string json, SaveLoadStatus status, int source, SaveData expected)
    {
        SaveLoadResult r = SaveLoader.Load(json);
        if (r == null) return "Load(" + json + ") 가 null 을 돌려줌";
        if (r.Status != status || r.SourceVersion != source)
            return "Load(" + json + ") 기대 " + status + "/v" + source + " / 결과 " + r.Status + "/v" + r.SourceVersion + " " + Fmt(r.Data);
        string want = Fmt(expected), got = Fmt(r.Data);
        return want == got ? null : "Load(" + json + ") 데이터 기대 " + want + " / 결과 " + got;
    }

    static string Json(System.Text.Json.Nodes.JsonNode n) => n == null ? "null" : n.ToJsonString();

    // 단계 함수의 결과를 속성 순서와 무관하게 요약한다.
    static string Shape(System.Text.Json.Nodes.JsonObject o)
    {
        if (o == null) return "null";
        System.Func<System.Text.Json.Nodes.JsonNode, string> V = n => n == null ? "없음" : n.ToJsonString();
        string inv = "없음";
        if (o["inventory"] is System.Text.Json.Nodes.JsonArray arr)
        {
            var parts = new System.Collections.Generic.List<string>();
            foreach (var e in arr) parts.Add(e is System.Text.Json.Nodes.JsonObject x ? x["id"]?.GetValue<string>() + "x" + V(x["count"]) : V(e));
            inv = "[" + string.Join(",", parts) + "]";
        }
        string wallet = o["wallet"] is System.Text.Json.Nodes.JsonObject w ? V(w["gold"]) + "/" + V(w["gems"]) : V(o["wallet"]);
        return "version=" + V(o["version"]) + " gold=" + V(o["gold"]) + " items=" + V(o["items"]) + " inventory=" + inv + " wallet=" + wallet;
    }

    public static void Main()
    {
        Run("v1-without-version-migrates", () =>
            Check("{\"gold\":120,\"hp\":80,\"items\":[\"potion\",\"sword\",\"potion\",\"shield\",\"potion\"]}", SaveLoadStatus.Migrated, 1, Data(120, 0, 80, ("potion", 3), ("sword", 1), ("shield", 1)))
            ?? Check("{\"version\":1,\"items\":[]}", SaveLoadStatus.Migrated, 1, Data(0, 0, 80))
            ?? Check("{\"version\":null,\"gold\":5}", SaveLoadStatus.Migrated, 1, Data(5, 0, 80)));

        Run("v2-runs-only-later-steps", () =>
            Check("{\"version\":2,\"gold\":7,\"inventory\":[{\"id\":\"bomb\",\"count\":4},{\"id\":\"ether\",\"count\":1}]}", SaveLoadStatus.Migrated, 2, Data(7, 0, 80, ("bomb", 4), ("ether", 1)))
            ?? Check("{\"version\":2}", SaveLoadStatus.Migrated, 2, Data(0, 0, 80)));

        Run("step-functions", () =>
        {
            System.Func<string, System.Text.Json.Nodes.JsonObject> P = j => System.Text.Json.Nodes.JsonNode.Parse(j).AsObject();
            var a = SaveMigrations.V1ToV2(P("{\"gold\":3,\"items\":[\"a\",\"b\",\"a\"]}"));
            string got = Shape(a);
            if (got != "version=2 gold=3 items=없음 inventory=[ax2,bx1] wallet=없음")
                return "V1ToV2({gold:3, items:[a,b,a]}) 기대 version=2 gold=3 items=없음 inventory=[ax2,bx1] wallet=없음 / 결과 " + got + " " + Json(a);
            var b = SaveMigrations.V1ToV2(P("{}"));
            got = Shape(b);
            if (got != "version=2 gold=없음 items=없음 inventory=[] wallet=없음") return "V1ToV2({}) 기대 version=2 gold=없음 items=없음 inventory=[] wallet=없음 / 결과 " + got + " " + Json(b);
            var c = SaveMigrations.V2ToV3(P("{\"version\":2,\"gold\":5,\"inventory\":[{\"id\":\"a\",\"count\":2}]}"));
            got = Shape(c);
            if (got != "version=3 gold=없음 items=없음 inventory=[ax2] wallet=5/0") return "V2ToV3({version:2, gold:5, inventory:[ax2]}) 기대 version=3 gold=없음 items=없음 inventory=[ax2] wallet=5/0 / 결과 " + got + " " + Json(c);
            try { SaveMigrations.V1ToV2(P("{\"items\":[\"a\",3]}")); return "V1ToV2({items:[a,3]}) 가 SaveFormatException 을 던지지 않음"; }
            catch (SaveFormatException) { return null; }
        });

        Run("defaults-only-when-missing", () =>
            Check("{\"version\":3,\"wallet\":{\"gold\":5},\"settings\":{\"bgmVolume\":0}}", SaveLoadStatus.Loaded, 3, Data(5, 0, 0))
            ?? Check("{\"version\":3,\"settings\":null,\"inventory\":null}", SaveLoadStatus.Loaded, 3, Data(0, 0, 80))
            ?? Check("{\"version\":3,\"wallet\":{\"gold\":0,\"gems\":0},\"settings\":{},\"nickname\":\"kim\"}", SaveLoadStatus.Loaded, 3, Data(0, 0, 80))
            ?? Check("{\"version\":2,\"gold\":0}", SaveLoadStatus.Migrated, 2, Data(0, 0, 80)));

        Run("future-version-untouched", () =>
            Check("{\"version\":4,\"wallet\":{\"gold\":9}}", SaveLoadStatus.FutureVersion, 4, null)
            ?? Check("{\"version\":99,\"wallet\":\"not-an-object\"}", SaveLoadStatus.FutureVersion, 99, null));

        Run("corrupt-inputs", () =>
        {
            string[] bad =
            {
                null, "", "not json", "[]", "42", "{\"version\":\"3\"}", "{\"version\":0}", "{\"version\":-1}", "{\"version\":2.5}",
                "{\"version\":true}", "{\"items\":[\"a\",1]}", "{\"items\":\"potion\"}", "{\"gold\":\"many\"}",
                "{\"version\":3,\"inventory\":[{\"id\":\"a\",\"count\":0}]}", "{\"version\":3,\"inventory\":[{\"count\":1}]}",
                "{\"version\":3,\"settings\":{\"bgmVolume\":150}}", "{\"version\":3,\"wallet\":[]}", "{\"version\":3,\"wallet\":{\"gold\":-5}}",
            };
            foreach (string json in bad)
            {
                string e = Check(json, SaveLoadStatus.Corrupt, 0, null);
                if (e != null) return json == null ? "Load(null): " + e : e;
            }
            return null;
        });

        Run("random-vs-reference", () =>
        {
            uint s = 20261122u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            string[] ids = { "potion", "ether", "sword", "shield", "bomb" };
            for (int t = 0; t < 300; t++)
            {
                // v1: 이름 배열 → 처음 나온 순서로 묶음
                int gold = rnd(4) == 0 ? -1 : rnd(100000);
                var items = new System.Collections.Generic.List<string>();
                for (int k = rnd(31); k > 0; k--) items.Add(ids[rnd(ids.Length)]);
                var json = new System.Text.StringBuilder("{");
                if (rnd(3) == 0) json.Append("\"version\":1,");
                if (gold >= 0) json.Append("\"gold\":").Append(gold).Append(',');
                if (rnd(2) == 0) json.Append("\"hp\":").Append(rnd(100)).Append(',');
                json.Append("\"items\":[");
                for (int k = 0; k < items.Count; k++) json.Append(k > 0 ? "," : "").Append('"').Append(items[k]).Append('"');
                json.Append("]}");
                var expected = new SaveData { Gold = gold < 0 ? 0 : gold };
                foreach (string id in items)
                {
                    int at = expected.Inventory.FindIndex(x => x.Id == id);
                    if (at < 0) expected.Inventory.Add(new ItemStack(id, 1));
                    else expected.Inventory[at] = new ItemStack(id, expected.Inventory[at].Count + 1);
                }
                string e = Check(json.ToString(), SaveLoadStatus.Migrated, 1, expected);
                if (e != null) return "무작위 v1 " + t + "번: " + e;

                // v3: Save 로 쓴 것을 다시 읽으면 그대로(0 값 포함)
                var data = Data(rnd(3) == 0 ? 0 : rnd(1000000), rnd(3) == 0 ? 0 : rnd(5000), rnd(101));
                for (int k = rnd(6); k > 0; k--) data.Inventory.Add(new ItemStack(ids[rnd(ids.Length)], 1 + rnd(99)));
                e = Check(SaveLoader.Save(data), SaveLoadStatus.Loaded, 3, data);
                if (e != null) return "무작위 v3 왕복 " + t + "번: " + e;
            }
            return null;
        });
    }
}

