// 여러 파일을 한 곳에 모아 보여 줍니다. 각 구역의 첫 줄이 파일 경로입니다.

// ===== Assets/Game/Gameplay/EnemySpawner.cs (런타임 코드: UnityEditor 를 쓰지 않는다) =====
using UnityEngine;

public class EnemySpawner : MonoBehaviour
{
    [SerializeField] private float interval = 2f;
    [SerializeField] private GameObject goblinPrefab;   // 프리팹 참조는 직렬화해 빌드에서도 유지된다
    private float _timer;

    private void Update()
    {
        if (goblinPrefab == null) return;
        _timer += Time.deltaTime;
        if (_timer < interval) return;
        _timer = 0f;
        Instantiate(goblinPrefab, transform.position, Quaternion.identity);
    }
}

// ===== Assets/Game/Gameplay/Editor/EnemySpawnerEditor.cs (에디터 코드: Game.Gameplay.Editor 어셈블리) =====
using UnityEditor;
using UnityEngine;

[CustomEditor(typeof(EnemySpawner))]
public class EnemySpawnerEditor : Editor
{
    private const string GoblinPath = "Assets/Prefabs/Goblin.prefab";

    public override void OnInspectorGUI()
    {
        DrawDefaultInspector();
        if (GUILayout.Button("Goblin 프리팹 채우기"))
        {
            // 저작 시점에만 AssetDatabase 로 찾아서 직렬화 필드에 넣는다.
            serializedObject.FindProperty("goblinPrefab").objectReferenceValue =
                AssetDatabase.LoadAssetAtPath<GameObject>(GoblinPath);
            serializedObject.ApplyModifiedProperties();
        }
    }
}

