using System;

// 고정 스텝마다 한 번 불리는 시뮬레이션(Unity 의 FixedUpdate 자리).
public interface IFixedStepTarget
{
    void FixedStep();
}

// 매 고정 스텝 같은 거리만큼 나아가는 투사체. 렌더링용 보간 위치(RenderX)만 구현하세요.
public sealed class Projectile : IFixedStepTarget
{
    public Projectile(double startX, double speedPerStep)
    {
        PreviousX = CurrentX = startX;
        SpeedPerStep = speedPerStep;
    }

    public double SpeedPerStep { get; }
    public double PreviousX { get; private set; }   // 직전 고정 스텝이 끝났을 때의 위치
    public double CurrentX { get; private set; }    // 마지막 고정 스텝이 끝났을 때의 위치

    public void FixedStep()
    {
        PreviousX = CurrentX;
        CurrentX += SpeedPerStep;
    }

    // 화면에 그릴 위치: PreviousX 에서 CurrentX 쪽으로 alpha 만큼 선형 보간한다.
    // 시뮬레이션 상태는 바꾸지 않는다. 그래서 화면은 마지막 고정 스텝보다 최대 한 스텝 늦게 보인다.
    public double RenderX(double alpha) => PreviousX + (CurrentX - PreviousX) * alpha;
}

// Unity 의 고정 업데이트 모델을 정수 마이크로초로 옮긴 시계.
// 불변식: Advance 가 끝나면 항상 0 <= TimeMicros - FixedTimeMicros < FixedStepMicros.
public sealed class FixedStepClock
{
    private long _time;        // Time.time 에 해당: 줄인 델타의 합
    private long _fixedTime;   // 고정 시간: 실행한 스텝 수 × 고정 스텝
    private long _steps;

    public FixedStepClock(long fixedStepMicros, long maxDeltaMicros)
    {
        if (fixedStepMicros <= 0) throw new ArgumentOutOfRangeException(nameof(fixedStepMicros));
        if (maxDeltaMicros < fixedStepMicros) throw new ArgumentOutOfRangeException(nameof(maxDeltaMicros));
        FixedStepMicros = fixedStepMicros;
        MaxDeltaMicros = maxDeltaMicros;
    }

    public long FixedStepMicros { get; }
    public long MaxDeltaMicros { get; }
    public long TimeMicros => _time;
    public long FixedTimeMicros => _fixedTime;
    public long StepCount => _steps;
    public double Alpha => (double)(_time - _fixedTime) / FixedStepMicros;

    // 한 프레임 동안 흐른 시간을 받아 필요한 만큼 target.FixedStep() 을 부르고, 이번 프레임에 실행한 스텝 수를 돌려준다.
    public int Advance(long frameDeltaMicros, IFixedStepTarget target)
    {
        if (frameDeltaMicros < 0) throw new ArgumentOutOfRangeException(nameof(frameDeltaMicros));
        if (target == null) throw new ArgumentNullException(nameof(target));

        // 1) 델타를 최대 허용 시간으로 줄이고 더한다. 넘친 시간은 버린다(나중에 따라잡지 않는다).
        _time += Math.Min(frameDeltaMicros, MaxDeltaMicros);

        // 2) 누적 시간이 고정 시간보다 한 스텝 이상 앞서 있는 동안 고정 스텝을 하나씩 실행한다.
        int ran = 0;
        while (_time - _fixedTime >= FixedStepMicros)
        {
            _fixedTime += FixedStepMicros;
            _steps++;
            ran++;
            target.FixedStep();
        }
        return ran;
    }
}

