    static string Steps(FixedStepClock c, Counter t, params long[] frames)
    {
        var parts = new System.Collections.Generic.List<string>();
        foreach (long d in frames)
        {
            int before = t.Calls, ran = c.Advance(d, t);
            parts.Add(ran == t.Calls - before ? ran.ToString() : ran + "(호출 " + (t.Calls - before) + ")");
        }
