    }

    static string State(FixedStepClock c) => "Time=" + c.TimeMicros + " Fixed=" + c.FixedTimeMicros + " Steps=" + c.StepCount + " Alpha=" + c.Alpha.ToString("R");

    static string Throws<T>(string what, System.Action a) where T : System.Exception
    {
