            string before = State(c);
            string e = Throws<System.ArgumentOutOfRangeException>("Advance(-1)", () => c.Advance(-1, t));
            if (e != null) return e;
            return State(c) == before && t.Calls == 2 ? null : "음수 델타 뒤 상태가 바뀜: " + before + " → " + State(c);
        });

        Run("interpolation-render", () =>
        {
            var c = new FixedStepClock(20000, 320000); var p = new Projectile(10.0, 3.0);
            c.Advance(30000, p);
            double x = p.RenderX(c.Alpha);
            if (!Near(c.Alpha, 0.5) || !Near(x, 11.5)) return "시작 10, 스텝당 3, 프레임 30000µs 뒤 기대 Alpha=0.5 RenderX=11.5 / 결과 Alpha=" + c.Alpha.ToString("R") + " RenderX=" + x.ToString("R");
            c.Advance(15000, p);
            x = p.RenderX(c.Alpha);
            if (!Near(c.Alpha, 0.25) || !Near(x, 13.75)) return "이어서 15000µs 뒤 기대 Alpha=0.25 RenderX=13.75 / 결과 Alpha=" + c.Alpha.ToString("R") + " RenderX=" + x.ToString("R");
            return Near(p.RenderX(0), p.PreviousX) && Near(p.RenderX(1), p.CurrentX) ? null : "RenderX(0) 은 PreviousX, RenderX(1) 은 CurrentX 여야 함";
        });

        Run("random-vs-reference", () =>
        {
            uint s = 20261122u;
            System.Func<int, int> rnd = n => { s = s * 1664525u + 1013904223u; return (int)((s >> 8) % (uint)n); };
            for (int r = 0; r < 300; r++)
            {
                long step = 1000 + rnd(49001), max = step * (1 + rnd(20));
                var c = new FixedStepClock(step, max); var t = new Counter();
                long refTime = 0, refFixed = 0, refSteps = 0;
                var log = new System.Text.StringBuilder();
                for (int f = 0; f < 60; f++)
                {
                    long d = rnd(5) == 0 ? rnd((int)System.Math.Min(int.MaxValue, 3 * max)) : rnd((int)(2 * step));
                    log.Append(d).Append(' ');
                    refTime += System.Math.Min(d, max);
                    int want = 0;
                    while (refTime - refFixed >= step) { refFixed += step; refSteps++; want++; }
                    int before = t.Calls, got = c.Advance(d, t);
                    double wantAlpha = (double)(refTime - refFixed) / step;
                    if (got != want || t.Calls - before != want || c.TimeMicros != refTime || c.FixedTimeMicros != refFixed || c.StepCount != refSteps || !Near(c.Alpha, wantAlpha))
                        return "무작위 " + r + "번(고정 " + step + "µs, 최대 " + max + "µs) 프레임 [" + log.ToString().TrimEnd() + "] 뒤 기대 스텝 " + want + " Time=" + refTime + " Fixed=" + refFixed + " Steps=" + refSteps + " / 결과 스텝 " + got + " " + State(c);
                }
            }
            // 같은 총시간을 다르게 나눠 넣어도(각 프레임 ≤ 최대) 스텝 수와 고정 시간이 같다.
            var whole = new FixedStepClock(20000, 1000000); var a = new Counter();
            whole.Advance(1000000, a);
            var split = new FixedStepClock(20000, 1000000); var b = new Counter();
            for (int i = 0; i < 60; i++) split.Advance(i < 40 ? 16667 : 16666, b);
            return whole.StepCount == 50 && split.StepCount == 50 && split.FixedTimeMicros == whole.FixedTimeMicros && Near(split.Alpha, whole.Alpha) ? null
                : "1초를 한 번에 넣은 경우와 60 프레임(16667µs × 40 + 16666µs × 20)으로 나눠 넣은 경우 모두 50 스텝이어야 함 / 결과 " + State(whole) + " | " + State(split);
        });
    }
}

