using UnityEngine;

// 전투·UI 어디서든 AudioManager.Instance.PlaySfx(...) 로 효과음을 낸다.
// 타이틀 씬에 하나가 배치되어 있고, 배치되지 않은 씬에서 먼저 쓰이면 스스로 만들어진다.
public class AudioManager : MonoBehaviour
{
    private static AudioManager s_instance;
    private static bool s_quitting;

    // 도메인 리로드를 끈 채 플레이 모드에 들어가면 static 값이 이전 세션에서 그대로 넘어온다.
    // SubsystemRegistration 은 첫 씬을 로드하기 전(씬 오브젝트의 Awake 전)에 불리므로 여기서 되돌린다.
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    private static void ResetStatics()
    {
        s_instance = null;
        s_quitting = false;
    }

    // 종료 중(OnApplicationQuit 이후)에는 null 을 돌려준다. 호출하는 쪽은 null 을 처리해야 한다.
    public static AudioManager Instance
    {
        get
        {
            if (s_quitting) return null; // 종료 중에는 새로 만들지 않는다
            if (s_instance == null)      // Unity 의 == 는 파괴된 오브젝트도 null 로 본다
            {
                var go = new GameObject("AudioManager");
                s_instance = go.AddComponent<AudioManager>();
            }
            return s_instance;
        }
    }

    // 이 매니저가 재생한 효과음 수 (실제 게임에서는 여기서 AudioSource.PlayOneShot 을 부른다)
    public int PlayedCount { get; private set; }

    public void PlaySfx(string clip)
    {
        PlayedCount++;
    }

    private void Awake()
    {
        if (s_instance != null && s_instance != this)
        {
            // Destroy 는 프레임이 끝날 때 실제로 파괴한다. 여기서 빠져나가지 않으면
            // 아래 코드가 곧 사라질 중복 오브젝트를 Instance 로 등록한다.
            Destroy(gameObject);
            return;
        }
        s_instance = this;
        DontDestroyOnLoad(gameObject);
    }

    private void OnApplicationQuit()
    {
        s_quitting = true; // 종료 시 모든 활성 오브젝트의 OnApplicationQuit 이 파괴보다 먼저 온다
    }

    private void OnDestroy()
    {
        if (s_instance == this) s_instance = null; // 중복이 파괴될 때 진짜 인스턴스를 지우지 않는다
    }
}

// 보스 방의 문. 씬을 떠나며 파괴될 때 닫히는 소리를 낸다.
public class BossDoor : MonoBehaviour
{
    public void Open()
    {
        AudioManager.Instance.PlaySfx("door_open");
    }

    private void OnDestroy()
    {
        // 앱 종료 중에는 오브젝트들의 OnDestroy 순서가 정해져 있지 않고 Instance 는 null 이다.
        // 씬 전환으로 파괴될 때는 매니저가 살아 있으므로 소리가 난다.
        var audio = AudioManager.Instance;
        if (audio != null) audio.PlaySfx("door_close");
    }
}

