// ===== 채점용 Unity 모델 (진짜 Unity 가 아니라, 문제에 필요한 동작만 문서대로 흉내 낸 것) =====
namespace UnityEngine
{
    public enum FindObjectsSortMode { None = 0, InstanceID = 1 }
    public enum RuntimeInitializeLoadType { AfterSceneLoad = 0, BeforeSceneLoad = 1, AfterAssembliesLoaded = 2, BeforeSplashScreen = 3, SubsystemRegistration = 4 }

    [System.AttributeUsage(System.AttributeTargets.Method, AllowMultiple = false)]
    public class RuntimeInitializeOnLoadMethodAttribute : System.Attribute
    {
        public RuntimeInitializeOnLoadMethodAttribute() { loadType = RuntimeInitializeLoadType.AfterSceneLoad; }
        public RuntimeInitializeOnLoadMethodAttribute(RuntimeInitializeLoadType loadType) { this.loadType = loadType; }
        public RuntimeInitializeLoadType loadType { get; private set; }
    }

    public class Object
    {
        private static int s_nextId = 1;
        internal readonly int __id = s_nextId++;
        internal bool __destroyed;
        public string name { get; set; }

        // Unity 처럼 파괴된 오브젝트는 null 과 같다고 비교한다. ?. ?? is null 은 이 연산자를 쓰지 않는다.
        public static bool operator ==(Object a, Object b)
        {
            bool an = (object)a == null || a.__destroyed, bn = (object)b == null || b.__destroyed;
            if ((object)a == null || (object)b == null) return an && bn;
            return a.__id == b.__id;
        }
        public static bool operator !=(Object a, Object b) => !(a == b);
        public static implicit operator bool(Object o) => !(o == null);
        public override bool Equals(object other) => other is Object o ? this == o : other == null && __destroyed;
        public override int GetHashCode() => __id;
        public override string ToString() => name;

        public static void Destroy(Object obj) => UnityModel.Engine.RequestDestroy(obj);
        public static void DontDestroyOnLoad(Object target) => UnityModel.Engine.MarkDontDestroy(target);
        public static T FindAnyObjectByType<T>() where T : Object { var a = UnityModel.Engine.Find<T>(); return a.Length > 0 ? a[0] : null; }
        public static T[] FindObjectsByType<T>(FindObjectsSortMode sortMode) where T : Object => UnityModel.Engine.Find<T>();
    }

    public sealed class GameObject : Object
    {
        internal readonly System.Collections.Generic.List<Component> __components = new System.Collections.Generic.List<Component>();
        internal bool __dontDestroy;
        public GameObject() : this("New Game Object") { }
        public GameObject(string name) { this.name = name; UnityModel.Engine.Register(this); }
        public GameObject gameObject => this;
        public T AddComponent<T>() where T : Component
        {
            var c = (T)System.Activator.CreateInstance(typeof(T), true);
            c.__go = this; c.name = name; __components.Add(c);
            UnityModel.Engine.OnComponentAdded(c);
            return c;
        }
        public T GetComponent<T>() where T : class
        {
            foreach (var c in __components) if (!c.__destroyed && c is T t) return t;
            return null;
        }
    }

    public class Component : Object
    {
        internal GameObject __go;
        public GameObject gameObject => __go;
        public T GetComponent<T>() where T : class => __go.GetComponent<T>();
    }
    public class Behaviour : Component { public bool enabled { get; set; } = true; }
    public class MonoBehaviour : Behaviour { }

    public static class Debug
    {
        public static void Log(object message) { }
        public static void LogWarning(object message) { }
        public static void LogError(object message) => UnityModel.Engine.Errors.Add("LogError: " + message);
    }

    public static class Application
    {
        public static event System.Action quitting;
        public static bool isPlaying => UnityModel.Engine.Playing;
        internal static void __Raise() => quitting?.Invoke();
        internal static void __Reset() => quitting = null;
    }
}

namespace UnityModel
{
    using UnityEngine;
    using System.Collections.Generic;
    using System.Reflection;

    public static class Engine
    {
        static readonly List<GameObject> s_objects = new List<GameObject>();
        static readonly List<Object> s_pending = new List<Object>();
        static readonly List<Component> s_deferredAwake = new List<Component>();
        static readonly Dictionary<FieldInfo, object> s_snapshot = new Dictionary<FieldInfo, object>();
        static readonly List<System.Type> s_userTypes = new List<System.Type>();
        static bool s_buildingScene, s_quitting;
        public static bool Playing;
        public static int CreatedDuringQuit;
        public static readonly List<string> Errors = new List<string>();

        const BindingFlags All = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly;

        // 프로그램 시작 = 도메인을 새로 만든 상태. 사용자 타입의 static 필드 초깃값을 기억해 둔다.
        public static void Boot()
        {
            foreach (var t in typeof(Engine).Assembly.GetTypes())
            {
                string ns = t.Namespace ?? "";
                if (ns == "UnityEngine" || ns == "UnityModel" || t.Name.StartsWith("__Judge") || t.IsGenericTypeDefinition) continue;
                if (t.DeclaringType != null && t.DeclaringType.Name.StartsWith("__Judge")) continue;
                s_userTypes.Add(t);
                System.Runtime.CompilerServices.RuntimeHelpers.RunClassConstructor(t.TypeHandle);
                foreach (var f in t.GetFields(All))
                    if (f.IsStatic && !f.IsLiteral && !f.IsInitOnly) s_snapshot[f] = f.GetValue(null);
            }
        }

        // 플레이 모드 진입. reloadDomain=false 는 Enter Play Mode Settings 에서 도메인 리로드를 끈 경우다.
        public static void EnterPlayMode(bool reloadDomain, System.Action buildFirstScene)
        {
            s_objects.Clear(); s_pending.Clear(); s_deferredAwake.Clear(); Errors.Clear();
            CreatedDuringQuit = 0; s_quitting = false; Playing = true;
            if (reloadDomain) { foreach (var kv in s_snapshot) kv.Key.SetValue(null, kv.Value); Application.__Reset(); }
            InvokeInit(RuntimeInitializeLoadType.SubsystemRegistration);
            InvokeInit(RuntimeInitializeLoadType.AfterAssembliesLoaded);
            InvokeInit(RuntimeInitializeLoadType.BeforeSplashScreen);
            BuildScene(buildFirstScene, true);
            InvokeInit(RuntimeInitializeLoadType.AfterSceneLoad);
        }

        // SceneManager.LoadScene(Single) 의 모델: DontDestroyOnLoad 가 아닌 오브젝트를 파괴한 뒤 새 씬을 올린다.
        public static void LoadScene(System.Action build)
        {
            foreach (var go in s_objects.ToArray()) if (!go.__dontDestroy) DestroyNow(go);
            BuildScene(build, false);
        }

        // 프레임 끝: Destroy 로 예약된 오브젝트를 실제로 파괴한다(OnDestroy 호출).
        public static void EndFrame()
        {
            while (s_pending.Count > 0) { var o = s_pending[0]; s_pending.RemoveAt(0); DestroyNow(o); }
        }

        // 앱 종료: 모든 활성 오브젝트에 OnApplicationQuit 을 보낸 뒤 orderKey 가 작은 오브젝트부터 파괴한다.
        public static void Quit(System.Func<GameObject, int> orderKey)
        {
            s_quitting = true;
            foreach (var go in s_objects.ToArray()) foreach (var c in go.__components.ToArray()) Send(c, "OnApplicationQuit");
            try { Application.__Raise(); } catch (System.Exception e) { Errors.Add("Application.quitting: " + e.GetType().Name); }
            var order = s_objects.ToArray();
            System.Array.Sort(order, (a, b) => orderKey(a).CompareTo(orderKey(b)));
            foreach (var go in order) DestroyNow(go);
            Playing = false;
        }

        public static void Spawn<T>(string name) where T : Component => new GameObject(name).AddComponent<T>();

        public static T[] Find<T>() where T : Object
        {
            var r = new List<T>();
            foreach (var go in s_objects) { if (go is T g) r.Add(g); foreach (var c in go.__components) if (!c.__destroyed && c is T t) r.Add(t); }
            return r.ToArray();
        }

        public static int LiveObjectsNamed(string prefix)
        {
            int n = 0;
            foreach (var go in s_objects) if (go.name.StartsWith(prefix)) n++;
            return n;
        }

        internal static void Register(GameObject go) { s_objects.Add(go); if (s_quitting) CreatedDuringQuit++; }
        internal static void OnComponentAdded(Component c) { if (s_buildingScene) s_deferredAwake.Add(c); else Send(c, "Awake"); }
        internal static void MarkDontDestroy(Object o) { var go = o as GameObject ?? (o as Component)?.__go; if ((object)go != null) go.__dontDestroy = true; }
        internal static void RequestDestroy(Object o) { if ((object)o != null && !o.__destroyed && !s_pending.Contains(o)) s_pending.Add(o); }

        static void BuildScene(System.Action build, bool first)
        {
            s_buildingScene = true;
            try { build?.Invoke(); } finally { s_buildingScene = false; }
            if (first) InvokeInit(RuntimeInitializeLoadType.BeforeSceneLoad);
            var list = s_deferredAwake.ToArray(); s_deferredAwake.Clear();
            foreach (var c in list) Send(c, "Awake");
        }

        static void DestroyNow(Object o)
        {
            if ((object)o == null || o.__destroyed) return;
            if (o is GameObject go)
            {
                foreach (var c in go.__components.ToArray()) if (!c.__destroyed) { Send(c, "OnDestroy"); c.__destroyed = true; }
                go.__destroyed = true; s_objects.Remove(go);
            }
            else if (o is Component c) { Send(c, "OnDestroy"); c.__destroyed = true; c.__go.__components.Remove(c); }
        }

        static void Send(Component c, string message)
        {
            for (var t = c.GetType(); t != null && t != typeof(MonoBehaviour); t = t.BaseType)
            {
                var m = t.GetMethod(message, All & ~BindingFlags.Static, null, System.Type.EmptyTypes, null);
                if (m == null) continue;
                try { m.Invoke(c, null); }
                catch (TargetInvocationException e) { Errors.Add(c.GetType().Name + "." + message + " 에서 " + e.InnerException.GetType().Name); }
                return;
            }
        }

        static void InvokeInit(RuntimeInitializeLoadType when)
        {
            foreach (var t in s_userTypes)
                foreach (var m in t.GetMethods(All))
                {
                    var a = m.GetCustomAttribute<RuntimeInitializeOnLoadMethodAttribute>();
                    if (a == null || !m.IsStatic || a.loadType != when) continue;
                    try { m.Invoke(null, null); }
                    catch (TargetInvocationException e) { Errors.Add(t.Name + "." + m.Name + " 에서 " + e.InnerException.GetType().Name); }
                }
        }
    }
}

public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "테스트 코드에서 예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Errs(string when) => UnityModel.Engine.Errors.Count == 0 ? null : when + ": 메시지 함수에서 예외 " + string.Join(", ", UnityModel.Engine.Errors);
    static int Managers() => UnityEngine.Object.FindObjectsByType<AudioManager>(UnityEngine.FindObjectsSortMode.None).Length;
    static AudioManager Placed() => UnityEngine.Object.FindAnyObjectByType<AudioManager>();
    static void Title() => UnityModel.Engine.Spawn<AudioManager>("AudioManager (타이틀 씬 배치)");
    static void Boss() { UnityModel.Engine.Spawn<BossDoor>("BossDoor"); }
    static void TitleWithDoor() { Title(); Boss(); }
    static string Same(AudioManager got, AudioManager want, string when)
        => (object)got == (object)want ? null : when + ": Instance 가 기대한 매니저가 아님 (결과 " + ((object)got == null ? "null" : got.name + ((bool)got ? "" : ", 파괴됨")) + ")";

    public static void Main()
    {
        UnityModel.Engine.Boot();

        Run("lazy-create-once", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, null);
            var a = AudioManager.Instance; var b = AudioManager.Instance;
            if ((object)a == null) return "빈 씬에서 Instance 가 null";
            if ((object)a != (object)b) return "Instance 를 두 번 읽었더니 서로 다른 매니저";
            a.PlaySfx("hit");
            return Managers() != 1 ? "살아 있는 AudioManager 기대 1 / 결과 " + Managers() : a.PlayedCount != 1 ? "PlayedCount 기대 1" : Errs("빈 씬");
        });

        Run("scene-placed-manager-is-used", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, Title);
            var placed = Placed();
            return Same(AudioManager.Instance, placed, "타이틀 씬 시작") ?? (Managers() != 1 ? "매니저 수 기대 1 / 결과 " + Managers() : null) ?? Errs("타이틀 씬 시작");
        });

        Run("reload-title-same-frame", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, Title);
            var original = AudioManager.Instance;
            UnityModel.Engine.LoadScene(Title); // 타이틀 씬 다시 로드: 배치된 매니저가 하나 더 생긴다
            return Same(AudioManager.Instance, original, "타이틀 씬을 다시 로드한 같은 프레임") ?? Errs("재로드");
        });

        Run("reload-title-next-frame", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, Title);
            var original = AudioManager.Instance;
            UnityModel.Engine.LoadScene(Title);
            UnityModel.Engine.EndFrame();
            var now = AudioManager.Instance;
            string e = Same(now, original, "타이틀 씬 재로드 다음 프레임");
            if (e != null) return e;
            if (Managers() != 1) return "재로드 다음 프레임: 살아 있는 AudioManager 기대 1 / 결과 " + Managers();
            if (UnityModel.Engine.LiveObjectsNamed("AudioManager") != 1) return "중복 매니저의 GameObject 가 남아 있음 (AudioManager 로 시작하는 GameObject " + UnityModel.Engine.LiveObjectsNamed("AudioManager") + "개)";
            now.PlaySfx("ui_click");
            return original.PlayedCount != 1 ? "효과음이 원래 매니저로 가지 않음" : Errs("재로드");
        });

        Run("scene-change-plays-door-close", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, TitleWithDoor);
            var m = AudioManager.Instance;
            UnityEngine.Object.FindAnyObjectByType<BossDoor>().Open();
            UnityModel.Engine.LoadScene(null); // 보스 방을 떠난다: 문이 파괴되며 닫히는 소리
            UnityModel.Engine.EndFrame();
            return Errs("씬 전환") ?? (m.PlayedCount != 2 ? "문 열림 + 닫힘 효과음 기대 2 / 결과 " + m.PlayedCount : null);
        });

        Run("quit-manager-destroyed-first", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, TitleWithDoor);
            UnityModel.Engine.Quit(go => go.name.StartsWith("AudioManager") ? 0 : 1);
            return Errs("종료(매니저가 먼저 파괴)") ?? (UnityModel.Engine.CreatedDuringQuit != 0 ? "종료 도중에 GameObject 가 " + UnityModel.Engine.CreatedDuringQuit + "개 새로 만들어짐" : null);
        });

        Run("quit-manager-destroyed-last", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, TitleWithDoor);
            UnityModel.Engine.Quit(go => go.name.StartsWith("AudioManager") ? 1 : 0);
            return Errs("종료(문이 먼저 파괴)") ?? (UnityModel.Engine.CreatedDuringQuit != 0 ? "종료 도중에 GameObject 가 " + UnityModel.Engine.CreatedDuringQuit + "개 새로 만들어짐" : null);
        });

        Run("replay-without-domain-reload", () =>
        {
            UnityModel.Engine.EnterPlayMode(true, Title);
            AudioManager.Instance.PlaySfx("hit");
            UnityModel.Engine.Quit(go => 0);
            UnityModel.Engine.EnterPlayMode(false, Title); // 도메인 리로드 없이 두 번째 플레이
            var placed = Placed();
            string e = Errs("두 번째 플레이 시작") ?? Same(AudioManager.Instance, placed, "도메인 리로드 없이 다시 플레이한 타이틀 씬");
            if (e != null) return e;
            if (Managers() != 1) return "두 번째 플레이: 매니저 수 기대 1 / 결과 " + Managers();
            UnityModel.Engine.Quit(go => 0);
            UnityModel.Engine.EnterPlayMode(false, null); // 세 번째 플레이: 매니저가 배치되지 않은 씬
            var m = AudioManager.Instance;
            if ((object)m == null || !(bool)m) return "도메인 리로드 없이 세 번째 플레이(빈 씬): Instance 가 null";
            return Managers() != 1 ? "세 번째 플레이: 매니저 수 기대 1 / 결과 " + Managers() : Errs("세 번째 플레이");
        });
    }
}

