problems.solutionCode:
using System;
using System.Threading;

public enum CastResult { Completed, TimedOut, Cancelled }

// 스킬이 기다리는 애니메이션 이벤트 하나. 이 단계의 대기가 시작된 시각부터 TimeoutMs 안에 와야 한다.
public readonly struct CastStep
{
    public readonly string EventName;
    public readonly long TimeoutMs;

    public CastStep(string eventName, long timeoutMs)
    {
        EventName = eventName;
        TimeoutMs = timeoutMs;
    }
}

// 바뀌지 않는 스킬 정의 (ScriptableObject 에서 읽어 온 값이라고 생각하세요)
public sealed class AbilityDefinition
{
    public readonly string Id;
    public readonly string Clip;       // 재생할 애니메이션 클립 이름
    public readonly CastStep[] Steps;  // 순서대로 기다릴 이벤트. 하나 이상

    public AbilityDefinition(string id, string clip, params CastStep[] steps)
    {
        Id = id;
        Clip = clip;
        Steps = steps;
    }
}

// MonoBehaviour 어댑터가 Animator.CrossFade 로 이어 주는 출력 포트
public interface IAnimationPort
{
    void Play(string clip);
}

// 엔진을 모르는 순수 C# 시전기. 시각(ms)과 애니메이션 이벤트는 바깥에서 넣어 준다.
public sealed class AbilityExecutor
{
    private readonly IAnimationPort _animation;

    // 진행 중인 시전. _ability 가 null 이면 시전 중이 아니다.
    private AbilityDefinition _ability;
    private Action<string> _onStep;
    private Action<CastResult> _onFinished;
    private CancellationTokenRegistration _registration;
    private int _step;
    private long _deadline;

    // Cast 를 부를 때마다 1 씩 커진다. 콜백이 끝난 뒤나 토큰 콜백이 불릴 때
    // "아직 내가 시작한 그 시전인가"를 이 번호로 확인한다.
    private long _castId;

    public AbilityExecutor(IAnimationPort animation)
    {
        _animation = animation ?? throw new ArgumentNullException(nameof(animation));
    }

    public bool IsCasting => _ability != null;

    // 시전 중인 스킬의 Id. 시전 중이 아니면 null
    public string CurrentAbilityId => _ability == null ? null : _ability.Id;

    public void Cast(AbilityDefinition ability, long nowMs, CancellationToken token,
                     Action<string> onStep, Action<CastResult> onFinished)
    {
        if (ability == null) throw new ArgumentNullException(nameof(ability));
        if (ability.Steps == null || ability.Steps.Length == 0)
            throw new ArgumentException("기다릴 단계가 하나 이상 있어야 합니다.", nameof(ability));

        // 진행 중인 시전을 먼저 끝낸다: 기한이 지났으면 TimedOut, 아니면 Cancelled.
        // 그 onFinished 가 또 다른 시전을 시작했다면 그것도 끝낸다.
        if (_ability != null && nowMs > _deadline) Finish(CastResult.TimedOut);
        while (_ability != null) Finish(CastResult.Cancelled);

        long id = ++_castId;
        if (token.IsCancellationRequested)
        {
            onFinished?.Invoke(CastResult.Cancelled); // 이미 취소된 토큰: 애니메이션도 재생하지 않는다
            return;
        }

        _ability = ability;
        _onStep = onStep;
        _onFinished = onFinished;
        _step = 0;
        _deadline = nowMs + ability.Steps[0].TimeoutMs;
        _animation.Play(ability.Clip);
        if (id != _castId || _ability == null) return; // Play 가 다시 들어와 시전을 바꾼 경우

        if (token.CanBeCanceled)
        {
            // 토큰이 다른 스레드에서 지금 막 취소됐다면 콜백이 Register 안에서 바로 실행될 수 있다.
            var registration = token.Register(() => CancelFrom(id));
            if (id == _castId && _ability != null) _registration = registration;
            else registration.Dispose();
        }
    }

    public void OnAnimationEvent(string clip, string eventName, long nowMs)
    {
        if (_ability == null) return;
        if (nowMs > _deadline) { Finish(CastResult.TimedOut); return; } // 기한을 넘겨 온 이벤트는 받지 않는다

        // 다른 클립(블렌드 아웃 중인 이전 스킬)의 이벤트나 지금 단계가 아닌 이벤트는 무시한다.
        if (!string.Equals(clip, _ability.Clip, StringComparison.Ordinal)) return;
        if (!string.Equals(eventName, _ability.Steps[_step].EventName, StringComparison.Ordinal)) return;

        long id = _castId;
        _onStep?.Invoke(eventName);
        if (id != _castId || _ability == null) return; // onStep 안에서 시전이 끝났거나 새 시전이 시작됐다

        _step++;
        if (_step == _ability.Steps.Length) { Finish(CastResult.Completed); return; }
        _deadline = nowMs + _ability.Steps[_step].TimeoutMs; // 다음 단계의 대기는 이 이벤트 시각부터
    }

    public void Tick(long nowMs)
    {
        if (_ability != null && nowMs > _deadline) Finish(CastResult.TimedOut);
    }

    // 경직·넉다운: 진행 중인 시전을 Cancelled 로 끝낸다
    public void Interrupt()
    {
        if (_ability != null) Finish(CastResult.Cancelled);
    }

    private void CancelFrom(long id)
    {
        if (id == _castId && _ability != null) Finish(CastResult.Cancelled);
    }

    // 상태를 먼저 비우고 등록을 해제한 뒤 콜백을 부른다. 그래서 onFinished 안에서 Cast 를 다시 불러도 된다.
    private void Finish(CastResult result)
    {
        if (_ability == null) return;
        var onFinished = _onFinished;
        var registration = _registration;
        _ability = null;
        _onStep = null;
        _onFinished = null;
        _registration = default;
        registration.Dispose(); // 끝난 시전의 콜백을 토큰에서 떼어 낸다 (토큰 콜백 안에서 불려도 안전)
        onFinished?.Invoke(result);
    }
}

problems.explanation:
**왜 "이벤트를 기다린다"에는 기한과 취소가 함께 있어야 하는가.** Animation Event 는 클립 타임라인의 정해진 시점에 스크립트 함수를 부르는 장치입니다 [unity-animation-event-manual]. 경직 애니메이션으로 넘어가 그 클립이 이벤트 시점까지 재생되지 않으면 이벤트는 오지 않습니다(타임라인 정의에서 나오는 추론). 그래서 대기는 반드시 기한과 취소 경로를 함께 가져야 하고, 그 규칙은 엔진 없이 시험할 수 있는 곳에 둡니다. 시각을 바깥에서 넣어 주는 것이 테스트의 제어 가능성을 만든다는 점은 CMU 17-214 의 테스트 가능성 강의가 시계 주입 예로 설명합니다 [cmu-17214-03-testability].

**구조.** 진행 중인 시전은 (스킬, 단계 번호, 기한, 두 콜백, 토큰 등록, 시전 번호) 하나로 표현되고, 끝나는 모든 경로가 `Finish` 한 곳으로 모입니다.
- **기한:** 시각을 받는 세 호출이 먼저 `now > 기한` 을 확인하므로 결과가 `Tick` 을 부른 빈도와 무관합니다. 같은 프레임에서 `Update` 의 `Tick` 과 애니메이션 이벤트 중 무엇이 먼저 와도, 기한과 같은 시각의 이벤트는 받아들여집니다.
- **낡은 이벤트:** 클립 이름과 단계 이름을 함께 비교합니다. 어댑터는 `AnimationEvent.animatorClipInfo` 로 이벤트를 낸 클립을 알 수 있습니다 [unity-animationevent-api].
- **재진입:** `Finish` 는 상태를 먼저 비우고 등록을 해제한 뒤 마지막에 `onFinished` 를 부릅니다. `onStep` 뒤에는 시전 번호와 진행 여부를 다시 확인합니다. 그래서 콜백 안의 `Cast` · `Interrupt` · 토큰 취소가 이미 끝난 시전을 다음 단계로 진행시키거나 두 번 끝내지 못합니다.
- **토큰:** `Cancel()` 은 등록된 콜백을 동기적으로, 등록의 역순으로 실행합니다 [ms-cts-cancel]. 이미 취소된 토큰에 `Register` 하면 콜백이 그 자리에서 동기적으로 실행되므로 [ms-ct-register] 시작 전에 `IsCancellationRequested` 를 확인합니다. 콜백은 자기 시전 번호를 들고 있어 다른 시전을 끝내지 못하고, 시전이 끝나면 등록을 `Dispose` 해 토큰에서 떼어 냅니다. `Dispose` 는 콜백이 자기 자신을 해제하는 경우에는 기다리지 않는다고 문서에 적혀 있어 [ms-ctr-dispose] "토큰 콜백 → Finish → Dispose" 경로도 교착 없이 끝납니다(테스트의 토큰 취소 케이스가 이 경로를 지납니다).

**복잡도.** `Tick` · `OnAnimationEvent` 는 O(1) 이고 서수 문자열 비교만 하므로 대기 중에는 할당이 없습니다(테스트가 `GC.GetAllocatedBytesForCurrentThread` 로 확인). `Cast` 는 토큰 등록 때문에 클로저 등을 할당하며, 규칙상 허용됩니다.

**흔한 실수.** 토큰 콜백에 `() => Interrupt()` 를 걸고 해제하지 않기(끝난 시전의 토큰이 새 시전을 끊음), `onFinished` 를 상태 정리 전에 부르기(콜백 안의 새 시전이 지워지거나 콜백이 두 번 불림), 시간 초과를 `Tick` 에서만 판정하기(늦게 온 이벤트를 받아들임), `>=` 로 비교하기(기한과 같은 시각의 이벤트를 버림).

**실제 Unity 와 잇는 부분 (채점 대상 아님).** 아래 어댑터만 `UnityEngine` 을 씁니다. Animation Event 가 부르는 함수는 `AnimationEvent` 하나를 받을 수 있고 [unity-animation-event-manual], `destroyCancellationToken` 은 MonoBehaviour 가 파괴될 때 취소되는 토큰입니다 [unity-destroy-token-api]. 토큰이 취소되면 시전은 그 자리에서 `Cancelled` 로 한 번 끝나고, 그 뒤에는 그 시전의 어떤 콜백도 불리지 않습니다(QA 3). `Cancelled` 를 받는 쪽은 결과만 기록하고 파괴 중일 수 있는 오브젝트를 건드리지 않게 짭니다. 취소가 `OnDestroy` 와 정확히 어떤 순서로 일어나는지는 문서에 적혀 있지 않습니다. Animator 업데이트 모드 Normal 은 Update 루프에서 갱신되고 timeScale 과 무관한 UnscaledTime 이 따로 있으므로 [unity-animator-updatemode], 기한도 같은 게임 시간(`Time.timeAsDouble`)으로 재야 히트스톱이나 일시정지 중에 거짓 시간 초과가 나지 않습니다(추론).
```csharp
using System;
using UnityEngine;

public sealed class AbilityCaster : MonoBehaviour, IAnimationPort
{
    [SerializeField] private Animator animator;
    private AbilityExecutor _executor;
    private void Awake() => _executor = new AbilityExecutor(this);
    // CrossFade 는 상태 이름을 받는다: 여기서는 상태 이름을 클립 이름과 같게 둔다고 가정한다
    public void Play(string clip) => animator.CrossFade(clip, 0.1f);
    public void Cast(AbilityDefinition def, Action<string> onStep, Action<CastResult> onDone)
        => _executor.Cast(def, NowMs(), destroyCancellationToken, onStep, onDone);
    private void Update() => _executor.Tick(NowMs());
    // 클립의 Animation Event: 함수 이름 OnAbilityEvent, String 파라미터에 "Hit" / "End"
    public void OnAbilityEvent(AnimationEvent e)
        => _executor.OnAnimationEvent(e.animatorClipInfo.clip.name, e.stringParameter, NowMs());
    private static long NowMs() => (long)(Time.timeAsDouble * 1000.0);
}
```

### 흔한 오해
- **"`CancellationToken.Register` 에 건 콜백은 나중에(다음 프레임이나 스레드 풀에서) 실행되니, `Cancel()` 직후에는 아직 시전 중일 수 있다."** — Microsoft Learn 은 `Cancel()` 이 등록된 콜백을 동기적으로 LIFO 순서로 실행한다고 명시하고 [ms-cts-cancel], 이미 취소된 토큰에 등록하면 콜백이 즉시 동기적으로 실행된다고 적습니다 [ms-ct-register]. .NET 8 에서 실행해 보니 콜백은 `Cancel()` 을 부른 같은 스레드에서 반환 전에 실행됐고, 두 콜백은 등록 역순으로 불렸습니다. 그래서 콜백 안의 재진입을 반드시 설계에 넣어야 합니다.
- **"`CancellationTokenRegistration` 은 시전이 끝나면 저절로 정리되니 `Dispose` 하지 않아도 된다."** — `Dispose` 의 정의 자체가 "등록을 해제하고 콜백을 토큰에서 떼어 낸다"입니다 [ms-ctr-dispose]. 해제하지 않은 콜백은 토큰 소스에 남아 있다가 나중의 `Cancel()` 에서 실행됩니다(.NET 8 에서 확인: 해제한 콜백만 실행되지 않음). `destroyCancellationToken` 처럼 캐릭터 수명 내내 사는 토큰이면 끝난 시전마다 콜백과 클로저가 쌓이고, 콜백이 "지금 시전"을 끝내는 식이면 엉뚱한 시전을 끊습니다(`old-token-cannot-cancel-new-cast`).

tests.template:
{{USER_CODE}}

public static class __Judge
{
    sealed class Anim : IAnimationPort
    {
        public readonly System.Text.StringBuilder Log;
        public Anim(System.Text.StringBuilder log) { Log = log; }
        public void Play(string clip) { Log.Append("p:").Append(clip).Append(' '); }
    }

    static readonly AbilityDefinition Slash = new AbilityDefinition("Slash", "SlashClip", new CastStep("Hit", 300), new CastStep("End", 200));
    static readonly AbilityDefinition Dash = new AbilityDefinition("Dash", "DashClip", new CastStep("Go", 150));
    static readonly AbilityDefinition Nova = new AbilityDefinition("Nova", "NovaClip", new CastStep("Charge", 400), new CastStep("Burst", 100), new CastStep("End", 250));

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 시전 n 번의 콜백을 로그에 남기는 Cast
    static void C(AbilityExecutor ex, System.Text.StringBuilder log, int n, AbilityDefinition a, long now, System.Threading.CancellationToken tok)
        => ex.Cast(a, now, tok, s => log.Append('s').Append(n).Append(':').Append(s).Append(' '), r => log.Append('f').Append(n).Append(':').Append(r).Append(' '));

    static string Expect(System.Text.StringBuilder log, string want, string when)
    {
        string got = log.ToString().Trim();
        return got == want ? null : when + " — 기대 [" + want + "] / 결과 [" + got + "]";
    }

    static string State(AbilityExecutor ex, string id, string when)
        => ex.CurrentAbilityId == id && ex.IsCasting == (id != null) ? null : when + " — 시전 중 스킬 기대 " + (id ?? "없음") + " / 결과 " + (ex.CurrentAbilityId ?? "없음") + " (IsCasting=" + ex.IsCasting + ")";

    public static void Main()
    {
        var none = System.Threading.CancellationToken.None;

        Run("completes-in-order", () =>
        {
            var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
            C(ex, log, 1, Slash, 0, none);
            string e = State(ex, "Slash", "시전 직후");
            if (e != null) return e;
            ex.Tick(250); ex.OnAnimationEvent("SlashClip", "Hit", 280); ex.Tick(400); ex.OnAnimationEvent("SlashClip", "End", 470);
            ex.OnAnimationEvent("SlashClip", "End", 480); ex.Tick(5000);
            return Expect(log, "p:SlashClip s1:Hit s1:End f1:Completed", "Hit(280ms) 뒤 End(470ms), 이후 이벤트·Tick") ?? State(ex, null, "완료 뒤");
        });

        Run("ignores-stale-and-wrong-events", () =>
        {
            var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
            var smash = new AbilityDefinition("Smash", "SmashClip", new CastStep("Hit", 300));
            C(ex, log, 1, Slash, 0, none);
            ex.OnAnimationEvent("SlashClip", "End", 50);   // 아직 Hit 단계
            C(ex, log, 2, smash, 100, none);                // 새 스킬이 Slash 를 끊는다
            ex.OnAnimationEvent("SlashClip", "Hit", 120);  // 블렌드 아웃 중인 Slash 클립의 Hit: 이름은 같지만 다른 클립
            ex.OnAnimationEvent("SmashClip", "End", 130);  // 이 스킬에 없는 이벤트
            string e = Expect(log, "p:SlashClip f1:Cancelled p:SmashClip", "Slash 시전 중 Smash 시전, 이전 클립의 Hit") ?? State(ex, "Smash", "이전 클립의 이벤트 뒤");
            if (e != null) return e;
            ex.OnAnimationEvent("SmashClip", "Hit", 200);
            return Expect(log, "p:SlashClip f1:Cancelled p:SmashClip s2:Hit f2:Completed", "Smash 의 Hit(200ms)");
        });

        Run("timeout-boundaries", () =>
        {
            var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
            C(ex, log, 1, Dash, 1000, none); ex.Tick(1150); ex.OnAnimationEvent("DashClip", "Go", 1150); // 기한과 같은 시각: 받아들인다
            C(ex, log, 2, Dash, 2000, none); ex.Tick(2150); ex.Tick(2151);                             // 1ms 넘김: 시간 초과
            C(ex, log, 3, Dash, 3000, none); ex.OnAnimationEvent("DashClip", "Go", 3151);               // Tick 없이 늦게 온 이벤트
            C(ex, log, 7, Dash, 4000, none); C(ex, log, 8, Dash, 4151, none); ex.Interrupt();          // Tick 없이 기한 뒤의 새 시전
            string e = Expect(log, "p:DashClip s1:Go f1:Completed p:DashClip f2:TimedOut p:DashClip f3:TimedOut p:DashClip f7:TimedOut p:DashClip f8:Cancelled", "Dash(Go 150ms) 다섯 번");
            if (e != null) return e;
            log.Clear();
            C(ex, log, 4, Slash, 0, none); ex.OnAnimationEvent("SlashClip", "Hit", 100); ex.Tick(299); ex.Tick(300); // End 기한 = 100 + 200
            e = State(ex, "Slash", "Hit(100ms) 뒤 300ms");
            if (e != null) return e;
            ex.Tick(301);
            return Expect(log, "p:SlashClip s4:Hit f4:TimedOut", "Slash: Hit(100ms) 뒤 End 기한은 300ms");
        });

        Run("interrupt-and-token-cancel", () =>
        {
            var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
            ex.Interrupt(); ex.Tick(10); ex.OnAnimationEvent("SlashClip", "Hit", 10);   // 시전 중이 아닐 때는 아무 일도 없다
            C(ex, log, 1, Slash, 0, none); ex.Interrupt(); ex.Interrupt(); ex.Tick(9999); ex.OnAnimationEvent("SlashClip", "Hit", 9999);
            string e = Expect(log, "p:SlashClip f1:Cancelled", "Interrupt 두 번과 이후 입력");
            if (e != null) return e;
            log.Clear();
            var cts = new System.Threading.CancellationTokenSource();
            C(ex, log, 2, Nova, 0, cts.Token); ex.OnAnimationEvent("NovaClip", "Charge", 100);
            cts.Cancel();
            e = State(ex, null, "토큰 Cancel() 이 반환된 직후") ?? Expect(log, "p:NovaClip s2:Charge f2:Cancelled", "Charge 뒤 토큰 취소");
            if (e != null) return e;
            log.Clear();
            C(ex, log, 3, Dash, 200, none);
            C(ex, log, 4, Slash, 210, cts.Token);   // 이미 취소된 토큰: 진행 중인 Dash 를 끝내고, Slash 는 재생하지 않는다
            return Expect(log, "p:DashClip f3:Cancelled f4:Cancelled", "이미 취소된 토큰으로 시전") ?? State(ex, null, "이미 취소된 토큰으로 시전한 뒤");
        });

        Run("old-token-cannot-cancel-new-cast", () =>
        {
            var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
            var a = new System.Threading.CancellationTokenSource(); var b = new System.Threading.CancellationTokenSource();
            var c = new System.Threading.CancellationTokenSource(); var d = new System.Threading.CancellationTokenSource();
            C(ex, log, 1, Dash, 0, a.Token); ex.OnAnimationEvent("DashClip", "Go", 10);   // 완료
            C(ex, log, 2, Slash, 20, b.Token); ex.Interrupt();                           // 중단
            C(ex, log, 3, Nova, 30, c.Token);
            C(ex, log, 4, Slash, 40, d.Token);                                          // Nova 를 끊는다
            a.Cancel(); b.Cancel(); c.Cancel();
            string e = State(ex, "Slash", "끝난 시전들의 토큰을 취소한 뒤") ?? Expect(log, "p:DashClip s1:Go f1:Completed p:SlashClip f2:Cancelled p:NovaClip f3:Cancelled p:SlashClip", "끝난 시전의 토큰 a, b, c 취소");
            if (e != null) return e;
            var life = new System.Threading.CancellationTokenSource(); log.Clear();           // 캐릭터 수명 토큰을 여러 시전이 함께 쓴다
            C(ex, log, 5, Dash, 50, life.Token); ex.OnAnimationEvent("DashClip", "Go", 60);
            C(ex, log, 6, Dash, 70, life.Token);
            life.Cancel();
            return Expect(log, "f4:Cancelled p:DashClip s5:Go f5:Completed p:DashClip f6:Cancelled", "같은 수명 토큰으로 두 번 시전 후 취소") ?? State(ex, null, "수명 토큰 취소 뒤");
        });

        Run("reentrant-callbacks", () =>
        {
            var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
            bool chained = false; // 완료 콜백이 다음 스킬을 한 번만 시전한다
            ex.Cast(Dash, 0, none, s => log.Append("s1:" + s + " "), r => { log.Append("f1:" + r + " "); if (!chained) { chained = true; C(ex, log, 2, Slash, 5, none); } });
            ex.OnAnimationEvent("DashClip", "Go", 5);
            string e = Expect(log, "p:DashClip s1:Go f1:Completed p:SlashClip", "완료 콜백 안에서 다음 스킬 시전") ?? State(ex, "Slash", "완료 콜백 안에서 시전한 뒤");
            if (e != null) return e;
            ex.Interrupt(); log.Clear();
            ex.Cast(Slash, 100, none, s => { log.Append("s3:" + s + " "); ex.Interrupt(); }, r => log.Append("f3:" + r + " "));
            ex.OnAnimationEvent("SlashClip", "Hit", 150); ex.OnAnimationEvent("SlashClip", "End", 160);
            e = Expect(log, "p:SlashClip s3:Hit f3:Cancelled", "Hit 콜백 안에서 Interrupt");
            if (e != null) return e;
            log.Clear(); var cts = new System.Threading.CancellationTokenSource();
            ex.Cast(Dash, 200, cts.Token, s => { log.Append("s4:" + s + " "); cts.Cancel(); }, r => log.Append("f4:" + r + " "));
            ex.OnAnimationEvent("DashClip", "Go", 210);   // 마지막 단계의 콜백이 토큰을 취소한다
            e = Expect(log, "p:DashClip s4:Go f4:Cancelled", "마지막 단계 콜백 안에서 토큰 취소");
            if (e != null) return e;
            log.Clear();
            ex.Cast(Slash, 300, none, s => { log.Append("s5:" + s + " "); C(ex, log, 6, Nova, 310, none); }, r => log.Append("f5:" + r + " "));
            ex.OnAnimationEvent("SlashClip", "Hit", 310); ex.Tick(700); // Nova 의 Charge 기한 = 310 + 400
            e = Expect(log, "p:SlashClip s5:Hit f5:Cancelled p:NovaClip", "Hit 콜백 안에서 새 스킬 시전") ?? State(ex, "Nova", "Hit 콜백 안에서 시전한 Nova (700ms)");
            if (e != null) return e;
            ex.Tick(711);
            return Expect(log, "p:SlashClip s5:Hit f5:Cancelled p:NovaClip f6:TimedOut", "Nova 의 Charge 기한(710ms) 초과");
        });

        Run("steady-state-no-allocation", () =>
        {
            var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
            var cts = new System.Threading.CancellationTokenSource();
            C(ex, log, 1, Nova, 0, cts.Token);
            for (int i = 0; i < 2000; i++) { ex.Tick(i % 300); ex.OnAnimationEvent("SlashClip", "Hit", i % 300); ex.OnAnimationEvent("NovaClip", "Burst", i % 300); }
            long before = System.GC.GetAllocatedBytesForCurrentThread();
            for (int i = 0; i < 20000; i++) { ex.Tick(i % 300); ex.OnAnimationEvent("SlashClip", "Hit", i % 300); ex.OnAnimationEvent("NovaClip", "Burst", i % 300); }
            long bytes = System.GC.GetAllocatedBytesForCurrentThread() - before;
            return bytes == 0 ? State(ex, "Nova", "대기 중 입력 60000번 뒤") : "대기 중 Tick·무시되는 이벤트 60000번에 " + bytes + " 바이트 할당 (기대 0)";
        });

        Run("random-vs-reference", () =>
        {
            uint seed = 4242u;
            System.Func<int, int> rnd = n => { seed = seed * 1664525u + 1013904223u; return (int)((seed >> 8) % (uint)n); };
            var defs = new[] { Slash, Dash, Nova };
            string[] clips = { "SlashClip", "DashClip", "NovaClip" }, names = { "Hit", "End", "Go", "Charge", "Burst" };
            for (int run = 0; run < 200; run++)
            {
                var log = new System.Text.StringBuilder(); var ex = new AbilityExecutor(new Anim(log));
                var want = new System.Text.StringBuilder();
                var src = new System.Threading.CancellationTokenSource[3];
                for (int k = 0; k < 3; k++) src[k] = new System.Threading.CancellationTokenSource();
                var dead = new System.Threading.CancellationTokenSource(); dead.Cancel();
                AbilityDefinition cur = null; int curN = 0, step = 0; long deadline = 0; object curSrc = null;
                System.Action<string> fin = r => { want.Append('f').Append(curN).Append(':').Append(r).Append(' '); cur = null; };
                long now = 0; int castNo = 0;
                for (int op = 0; op < 60; op++)
                {
                    now += rnd(120);
                    int kind = rnd(10);
                    string what;
                    if (kind < 3)
                    {
                        var a = defs[rnd(3)]; int t = rnd(5); int n = ++castNo;
                        var s = t < 3 ? src[t] : t == 3 ? dead : null;
                        what = "Cast(" + a.Id + ")";
                        if (cur != null) fin(now > deadline ? "TimedOut" : "Cancelled");
                        if (s != null && s.IsCancellationRequested) want.Append('f').Append(n).Append(":Cancelled ");
                        else { want.Append("p:").Append(a.Clip).Append(' '); cur = a; curN = n; step = 0; deadline = now + a.Steps[0].TimeoutMs; curSrc = s; }
                        C(ex, log, n, a, now, s == null ? System.Threading.CancellationToken.None : s.Token);
                    }
                    else if (kind < 7)
                    {
                        string clip = clips[rnd(3)], name = names[rnd(5)];
                        what = "Event(" + clip + "," + name + ")";
                        if (cur != null)
                        {
                            if (now > deadline) fin("TimedOut");
                            else if (clip == cur.Clip && name == cur.Steps[step].EventName)
                            {
                                want.Append('s').Append(curN).Append(':').Append(name).Append(' ');
                                if (++step == cur.Steps.Length) fin("Completed"); else deadline = now + cur.Steps[step].TimeoutMs;
                            }
                        }
                        ex.OnAnimationEvent(clip, name, now);
                    }
                    else if (kind < 8) { what = "Tick"; if (cur != null && now > deadline) fin("TimedOut"); ex.Tick(now); }
                    else if (kind < 9) { what = "Interrupt"; if (cur != null) fin("Cancelled"); ex.Interrupt(); }
                    else
                    {
                        int k = rnd(3); what = "토큰" + k + " 취소";
                        if (cur != null && curSrc == src[k]) fin("Cancelled");
                        src[k].Cancel(); src[k] = new System.Threading.CancellationTokenSource();
                    }
                    string got = log.ToString(), exp = want.ToString();
                    if (got != exp || ex.IsCasting != (cur != null) || ex.CurrentAbilityId != (cur == null ? null : cur.Id))
                        return "무작위 " + run + "회차 " + op + "번째 조작 " + what + " (" + now + "ms) 뒤 불일치 — 기대 [" + exp.Trim() + "] / 결과 [" + got.Trim() + "], 시전 중 기대 " + (cur == null ? "없음" : cur.Id) + " / 결과 " + (ex.CurrentAbilityId ?? "없음");
                }
            }
            return null;
        });
    }
}

problems.scenario:
모바일 탄막 게임(Unity 6000.0 LTS, Burst 1.8, Unity.Mathematics)에서 화면의 탄 8,000 발을 매 프레임 움직이는 코드가 메인 스레드의 최상위 비용입니다. 동료가 이것을 Job System 과 Burst 로 옮긴 PR 을 올렸고, 여러분이 리뷰어입니다. "체인 탄"은 바로 앞 탄을 일정 간격으로 따라가는 탄입니다.

```csharp
[BurstCompile]
public struct MoveBulletsJob : IJobParallelFor
{
    public NativeArray<float3> positions;
    public NativeArray<float3> velocities;
    public NativeArray<byte> isChain;          // 1 이면 체인 탄
    public float3 chainOffset;
    public float dt;
    public static int groundHits;              // 바닥에 닿은 탄 수 (HUD 표시용)

    public void Execute(int i)
    {
        if (isChain[i] != 0 && i > 0)
            positions[i] = positions[i - 1] + chainOffset;   // 앞 탄을 따라간다
        else
            positions[i] += velocities[i] * dt;

        if (positions[i].y < 0f)
        {
            groundHits++;
            velocities[i] = float3.zero;
        }
    }
}

public class BulletSystem : MonoBehaviour
{
    [SerializeField] private HitCounterView hud;
    private readonly List<Bullet> _bullets = new List<Bullet>();   // Bullet 은 class

    private void Update()
    {
        int n = _bullets.Count;
        var positions = new NativeArray<float3>(n, Allocator.Persistent);
        var velocities = new NativeArray<float3>(n, Allocator.Persistent);
        var isChain = new NativeArray<byte>(n, Allocator.Persistent);
        for (int i = 0; i < n; i++)
        {
            positions[i] = _bullets[i].position;
            velocities[i] = _bullets[i].velocity;
            isChain[i] = (byte)(_bullets[i].isChain ? 1 : 0);
        }

        var job = new MoveBulletsJob { positions = positions, velocities = velocities, isChain = isChain,
                                       chainOffset = new float3(0f, 0f, -0.3f), dt = Time.deltaTime };
        JobHandle handle = job.Schedule(n, 1);
        handle.Complete();

        for (int i = 0; i < n; i++) _bullets[i].position = positions[i];
        hud.SetHits(MoveBulletsJob.groundHits);
    }
}
```

**질문: 이 PR 을 리뷰해 주세요. (1) Job System 과 NativeContainer 안전 시스템이 강제하는 규칙에 비춰 무엇이 잘못됐는지, (2) Burst 가 거부하거나 위험한 코드가 무엇인지, (3) NativeArray 의 할당과 해제를 어떻게 바꿀지, (4) 이 작업이 잡으로 옮겨서 실제로 빨라질 조건과 그것을 확인하는 방법을 답하세요.** Unity 6 매뉴얼과 Burst 1.8 매뉴얼에 적힌 내용을 근거로 하고, 추론은 추론이라고 밝혀 주세요.
